package com.yonwi.farming;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * What the account owns and carries: the bank (cached per account between sessions), the
 * inventory and worn items. Reads quests, diaries and items for the sidebar's unlocks.
 */
final class AccountItems {
  /** Ticks between account scans when nothing has prompted one. */
  private static final int SCAN_EVERY = 100;

  @Inject private Client client;
  @Inject private ItemManager itemManager;
  @Inject private ConfigManager configManager;
  @Inject private FarmingPlugin plugin;

  /** Item IDs in the bank, or null until it's been seen (or loaded from the saved copy). */
  private Set<Integer> bank;
  /** Everything owned (bank, inventory, worn), from the last account scan. */
  private volatile Set<Integer> owned = Collections.emptySet();
  private volatile boolean bankUnknown;
  private boolean scanDue;
  private int ticks;

  Set<Integer> bank() {
    return bank;
  }

  Set<Integer> owned() {
    return owned;
  }

  boolean bankUnknown() {
    return bankUnknown;
  }

  void forgetBank() {
    bank = null;
  }

  void scanSoon() {
    scanDue = true;
  }

  /** Scans when something prompted it, and every 100 ticks anyway. */
  void onTick() {
    if (scanDue || ++ticks % SCAN_EVERY == 0) scan();
  }

  /** The bank was seen: remember what's in it, here and in the account's saved settings. */
  void bankChanged(ItemContainer container) {
    bank = new LinkedHashSet<>();
    for (Item item : container.getItems())
      if (item.getId() > 0 && item.getQuantity() > 0) bank.add(itemManager.canonicalize(item.getId()));
    StringBuilder saved = new StringBuilder();
    for (int id : bank) saved.append(saved.length() == 0 ? "" : ",").append(id);
    configManager.setRSProfileConfiguration(FarmingPanel.GROUP, "bank", saved.toString());
  }

  /** Whether the inventory holds any of these item IDs (noted items have other IDs). */
  boolean holdingUnnoted(Set<Integer> ids) {
    ItemContainer inventory = client.getItemContainer(InventoryID.INV);
    if (inventory == null) return false;
    for (Item item : inventory.getItems()) if (ids.contains(item.getId())) return true;
    return false;
  }

  /** Whether the inventory or worn items hold any of these item IDs. */
  boolean carrying(Set<Integer> ids) {
    boolean carried = false;
    for (int container : new int[] {InventoryID.INV, InventoryID.WORN}) {
      ItemContainer items = client.getItemContainer(container);
      if (items != null) for (Item item : items.getItems()) carried |= ids.contains(item.getId());
    }
    return carried;
  }

  /** Reads quests, diaries and owned items, then tells the sidebar which unlocks are known. */
  private void scan() {
    scanDue = false;
    if (!plugin.isActive() || client.getGameState() != GameState.LOGGED_IN) return;
    if (bank == null) loadSavedBank();
    Set<Integer> ownedNow = new HashSet<>();
    Map<Integer, Integer> carried = new HashMap<>();
    if (bank != null) ownedNow.addAll(bank);
    for (int container : new int[] {InventoryID.INV, InventoryID.WORN}) {
      ItemContainer items = client.getItemContainer(container);
      if (items == null) continue;
      for (Item item : items.getItems())
        if (item.getId() > 0) {
          // Notes count as the item itself, e.g. noted protection payments.
          int id = itemManager.canonicalize(item.getId());
          ownedNow.add(id);
          carried.merge(id, item.getQuantity(), Integer::sum);
        }
    }
    bankUnknown = bank == null;
    owned = ownedNow;
    // Skill levels for Agility shortcuts on walking routes.
    Map<String, Integer> levels = new HashMap<>();
    for (Skill skill : Skill.values()) levels.put(skill.getName(), client.getRealSkillLevel(skill));
    WorldPath.setLevels(levels);
    AccountScan.Result result = AccountScan.scan(client, ownedNow, bank != null);
    result.carried = carried;
    result.pouch = plugin.kit().pouchRunes();
    result.spellbook = client.getVarbitValue(VarbitID.SPELLBOOK);
    plugin.toPanel(panel -> panel.updateAccount(result));
  }

  private void loadSavedBank() {
    String saved = configManager.getRSProfileConfiguration(FarmingPanel.GROUP, "bank");
    if (saved == null) return;
    bank = new LinkedHashSet<>();
    for (String id : saved.split(",")) if (!id.isEmpty()) bank.add(Integer.parseInt(id));
  }
}

package com.yonwi.farming;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/** Infers travel unlocks from quests, diaries and items the logged-in account owns. */
final class AccountScan {
  /** Unlocks that cannot be read from the client and always stay manual. */
  static final Set<String> MANUAL =
      new HashSet<>(
          Arrays.asList(
              "jewellery", "spirit", "kastori", "quetzal", "anglers", "catherbyPortal", "houseFairy",
              "fortisGlory"));

  static final Map<String, int[]> ITEMS = new LinkedHashMap<>();

  /** The Farming Guild's map regions, from RuneLite's Time Tracking FarmingWorld. */
  private static final Set<Integer> GUILD_REGIONS =
      new HashSet<>(Arrays.asList(4922, 5177, 5178, 5179, 4921, 4923, 4665, 4666, 4667));

  static {
    ITEMS.put(
        "herbExplorer",
        new int[] {
          ItemID.LUMBRIDGE_RING_EASY,
          ItemID.LUMBRIDGE_RING_MEDIUM,
          ItemID.LUMBRIDGE_RING_HARD,
          ItemID.LUMBRIDGE_RING_ELITE
        });
    ITEMS.put(
        "herbArdy",
        new int[] {
          ItemID.ARDY_CAPE_EASY,
          ItemID.ARDY_CAPE_MEDIUM,
          ItemID.ARDY_CAPE_HARD,
          ItemID.ARDY_CAPE_ELITE,
          ItemID.SKILLCAPE_MAX_ARDY
        });
    ITEMS.put("herbXeric", new int[] {ItemID.XERIC_TALISMAN});
    ITEMS.put("herbEcto", new int[] {ItemID.ECTOPHIAL, ItemID.ECTOPHIAL_EMPTY});
    ITEMS.put(
        "herbBasalt",
        new int[] {ItemID.STRONGHOLD_TELEPORT_BASALT, ItemID.WEISS_TELEPORT_BASALT});
    ITEMS.put("herbTrollheim", new int[] {ItemID.NZONE_TELETAB_TROLLHEIM});
    ITEMS.put("herbHarmonyTab", new int[] {ItemID.TELETAB_HARMONY});
    ITEMS.put("herbSack", FarmingData.IDS.get("Herb sack"));
    ITEMS.put("cape", FarmingData.IDS.get("Construction cape"));
    ITEMS.put("farmingCape", FarmingData.IDS.get("Farming cape"));
    ITEMS.put(
        "pouch",
        new int[] {
          ItemID.BH_RUNE_POUCH,
          ItemID.BH_RUNE_POUCH_TROUVER,
          ItemID.DIVINE_RUNE_POUCH,
          ItemID.DIVINE_RUNE_POUCH_TROUVER
        });
    ITEMS.put(
        "wealth",
        new int[] {
          ItemID.RING_OF_WEALTH_1,
          ItemID.RING_OF_WEALTH_2,
          ItemID.RING_OF_WEALTH_3,
          ItemID.RING_OF_WEALTH_4,
          ItemID.RING_OF_WEALTH_5,
          ItemID.RING_OF_WEALTH_I1,
          ItemID.RING_OF_WEALTH_I2,
          ItemID.RING_OF_WEALTH_I3,
          ItemID.RING_OF_WEALTH_I4,
          ItemID.RING_OF_WEALTH_I5
        });
    ITEMS.put(
        "slayer",
        new int[] {
          ItemID.SLAYER_RING_1,
          ItemID.SLAYER_RING_2,
          ItemID.SLAYER_RING_3,
          ItemID.SLAYER_RING_4,
          ItemID.SLAYER_RING_5,
          ItemID.SLAYER_RING_6,
          ItemID.SLAYER_RING_7,
          ItemID.SLAYER_RING_8,
          ItemID.SLAYER_RING_ETERNAL
        });
    ITEMS.put(
        "skills",
        new int[] {
          ItemID.JEWL_NECKLACE_OF_SKILLS_1,
          ItemID.JEWL_NECKLACE_OF_SKILLS_2,
          ItemID.JEWL_NECKLACE_OF_SKILLS_3,
          ItemID.JEWL_NECKLACE_OF_SKILLS_4,
          ItemID.JEWL_NECKLACE_OF_SKILLS_5,
          ItemID.JEWL_NECKLACE_OF_SKILLS_6
        });
    ITEMS.put("catherby", new int[] {ItemID.LUNAR_TABLET_CATHERBY_TELEPORT});
    ITEMS.put(
        "redirect", new int[] {ItemID.NZONE_TELETAB_TAVERLEY, ItemID.NZONE_TELETAB_BRIMHAVEN});
    ITEMS.put("pendant", new int[] {ItemID.PENDANT_OF_ATES});
    ITEMS.put("whistle", FarmingData.IDS.get("Quetzal whistle"));
    ITEMS.put("digsite", FarmingData.IDS.get("Digsite pendant"));
    ITEMS.put("lletya", FarmingData.IDS.get("Teleport crystal"));
  }

  static final class Result {
    /** True or false when known; keys missing from the map need manual selection. */
    final Map<String, Boolean> unlocks = new LinkedHashMap<>();

    String house;
    boolean bankSeen;
    /** Canonical IDs of everything carried, worn or banked. */
    Set<Integer> owned = new HashSet<>();
    /** Canonical ID to quantity for everything in the inventory and worn, notes unnoted. */
    Map<Integer, Integer> carried = new HashMap<>();
    /** Rune item ID to quantity inside the rune pouch. */
    Map<Integer, Integer> pouch = new LinkedHashMap<>();
    /** 0 standard, 1 ancient, 2 lunar, 3 arceuus. */
    int spellbook;
    /** Real Magic level. */
    int magic;
  }

  /**
   * Must run on the client thread while logged in. {@code owned} holds every item ID seen in the
   * inventory, equipment and (when {@code bankSeen}) the bank.
   */
  static Result scan(Client client, Set<Integer> owned, boolean bankSeen) {
    Result result = new Result();
    result.bankSeen = bankSeen;
    result.owned = owned;
    addOwnedItems(result, owned, bankSeen);
    addQuests(result, client);
    result.unlocks.put("herbHarmony", diary(client, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE));
    result.unlocks.put("faladorElite", diary(client, VarbitID.FALADOR_DIARY_ELITE_COMPLETE));
    result.magic = client.getRealSkillLevel(Skill.MAGIC);
    addAttas(result, client);
    addYieldDiaries(result, client);
    // The Lumbridge & Draynor elite diary lets fairy rings work without a staff.
    result.unlocks.put("staffless", diary(client, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE));
    QuestState fairy = Quest.FAIRYTALE_II__CURE_A_QUEEN.getState(client);
    if (fairy == QuestState.FINISHED) result.unlocks.put("fairy", true);
    else if (fairy == QuestState.NOT_STARTED) result.unlocks.put("fairy", false);
    // Owning the item is not enough when the destination itself is locked.
    if (!finished(client, Quest.BONE_VOYAGE)) result.unlocks.put("digsite", false);
    if (!finished(client, Quest.MOURNINGS_END_PART_I)) result.unlocks.put("lletya", false);
    if (!finished(client, Quest.GHOSTS_AHOY)) result.unlocks.put("herbEcto", false);
    result.house = house(client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION));
    return result;
  }

  /** Unlocks that come from owning an item: known when owned, or not owned once the bank's been seen. */
  private static void addOwnedItems(Result result, Set<Integer> owned, boolean bankSeen) {
    for (Map.Entry<String, int[]> item : ITEMS.entrySet()) {
      boolean has = false;
      for (int id : item.getValue()) has |= owned.contains(id);
      if (has) result.unlocks.put(item.getKey(), true);
      else if (bankSeen) result.unlocks.put(item.getKey(), false);
    }
  }

  private static void addQuests(Result result, Client client) {
    quest(result, "herbPriest", client, Quest.PRIEST_IN_PERIL);
    quest(result, "herbTroll", client, Quest.MY_ARMS_BIG_ADVENTURE);
    quest(result, "herbWeiss", client, Quest.MAKING_FRIENDS_WITH_MY_ARM);
    quest(result, "herbFortis", client, Quest.CHILDREN_OF_THE_SUN);
    quest(result, "varlamore", client, Quest.CHILDREN_OF_THE_SUN);
    quest(result, "gnome", client, Quest.TREE_GNOME_VILLAGE);
    quest(result, "fossil", client, Quest.BONE_VOYAGE);
    quest(result, "locus", client, Quest.THE_RIBBITING_TALE_OF_A_LILY_PAD_LABOUR_DISPUTE);
    result.unlocks.put(
        "summer", finished(client, Quest.TROUBLED_TORTUGANS) && client.getRealSkillLevel(Skill.AGILITY) >= 50);
  }

  /**
   * The Farming Guild's anima patch (varbit read only while in the guild, as RuneLite's Time
   * Tracking does): 8–15 is a living Attas plant, which boosts herb yield until it dies.
   */
  private static void addAttas(Result result, Client client) {
    Player player = client.getLocalPlayer();
    if (player == null || !GUILD_REGIONS.contains(player.getWorldLocation().getRegionID())) return;
    int anima = client.getVarbitValue(VarbitID.FARMING_TRANSMIT_M);
    result.unlocks.put("attas", anima >= 8 && anima <= 15);
  }

  /**
   * Herb yield and disease (OSRS wiki herb calculator): Kourend easy protects Hosidius, Kourend
   * hard adds 5% at Hosidius and the Farming Guild, Kandarin adds 5/10/15% at Catherby.
   */
  private static void addYieldDiaries(Result result, Client client) {
    result.unlocks.put("kourendEasy", diary(client, VarbitID.KOUREND_DIARY_EASY_COMPLETE));
    result.unlocks.put("kourendHard", diary(client, VarbitID.KOUREND_DIARY_HARD_COMPLETE));
    result.unlocks.put("kandarinMedium", diary(client, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE));
    result.unlocks.put("kandarinHard", diary(client, VarbitID.KANDARIN_DIARY_HARD_COMPLETE));
    result.unlocks.put("kandarinElite", diary(client, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE));
  }

  /** Where your house portal is, from its location varbit; null if unknown. */
  private static String house(int location) {
    switch (location) {
      case 0:
        return null;
      case 1:
        return "rimmington";
      case 2:
        return "taverley";
      case 5:
        return "brimhaven";
      default:
        return "other";
    }
  }

  private static boolean diary(Client client, int completeVarbit) {
    return client.getVarbitValue(completeVarbit) == 1;
  }

  private static boolean finished(Client client, Quest quest) {
    return quest.getState(client) == QuestState.FINISHED;
  }

  private static void quest(Result result, String key, Client client, Quest quest) {
    result.unlocks.put(key, finished(client, quest));
  }
}

package com.yonwi.farming;

import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * The button in the bank's top bar (where Quest Helper puts its own) that filters the bank down to
 * the run's kit. Only there while preparing a run.
 */
final class BankButton {
  private static final String BANK_TAG = "ultimate farming";
  // Quest Helper's exact button: 25px square at (408, 5) with a 19px icon inset by 3.
  private static final int X = 408;
  private static final int Y = 5;
  private static final int SIZE = 25;
  private static final int ICON_INSET = 3;

  @Inject private Client client;
  @Inject private ClientThread clientThread;
  @Inject private TagManager tagManager;
  @Inject private BankTagsService bankTags;
  @Inject private LayoutManager layoutManager;
  @Inject private FarmingPlugin plugin;

  private Widget button;
  private Widget icon;
  /** "Prepare run" pressed and the run not begun yet (no step done): the bank button's time. */
  private volatile boolean preparing;

  void registerFilter() {
    tagManager.registerTag(BANK_TAG, id -> plugin.kit().inBankFilter(id));
  }

  void unregisterFilter() {
    tagManager.unregisterTag(BANK_TAG);
  }

  /** On shutdown: closes the filter and hides the button. Client thread. */
  void remove() {
    if (filterOpen()) bankTags.closeBankTag();
    Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
    if (button != null && universe != null) {
      button.setHidden(true);
      if (icon != null) icon.setHidden(true);
      universe.revalidate();
    }
    button = null;
  }

  /** True while the bank shows this plugin's kit filter. */
  boolean filterOpen() {
    return BANK_TAG.equals(bankTags.getActiveTag());
  }

  boolean bankOpen() {
    return client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
  }

  /** Re-applies the kit filter so the bank shows exactly what's needed now. */
  void refreshFilter() {
    layoutManager.saveLayout(new Layout(BANK_TAG, plugin.kit().bankLayout()));
    bankTags.closeBankTag();
    bankTags.openBankTag(BANK_TAG, 0);
    style();
  }

  /** The bank button only shows while preparing: added or removed as that changes. */
  void setPreparing(boolean now) {
    boolean was = preparing;
    preparing = now;
    if (was != now) clientThread.invokeLater(this::update);
  }

  /** The bank opened. */
  void bankLoaded() {
    // Work out which spare variants to hide (e.g. a second quetzal whistle) before the bank shows
    // the filter, including when it was left open from last time.
    plugin.kit().bankLayout();
    clientThread.invokeLater(
        () -> {
          update();
          // Left open from last time: rebuild it from the current kit, as the run may have changed.
          if (preparing && filterOpen()) refreshFilter();
        });
  }

  void bankClosed() {
    button = null;
    icon = null;
  }

  /**
   * The bank button is only there while preparing a run; otherwise it's removed, along with the
   * kit filter if it was left showing, so the bank is untouched while you do other things.
   */
  void update() {
    Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
    if (universe == null) return;
    if (preparing) {
      add();
      if (button != null) button.setHidden(false);
      if (icon != null) icon.setHidden(false);
      style();
      return;
    }
    if (filterOpen()) bankTags.closeBankTag();
    if (button != null) button.setHidden(true);
    if (icon != null) icon.setHidden(true);
    universe.revalidate();
  }

  /** A farming button in the bank's top bar that shows every item the run needs. */
  private void add() {
    Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
    if (universe == null) return;
    Widget[] children = universe.getDynamicChildren();
    if (button != null && children != null && Arrays.asList(children).contains(button)) return;
    button = universe.createChild(-1, WidgetType.GRAPHIC);
    icon = universe.createChild(-1, WidgetType.GRAPHIC);
    for (Widget widget : new Widget[] {button, icon}) {
      int inset = widget == icon ? ICON_INSET : 0;
      widget.setOriginalX(X + inset);
      widget.setOriginalY(Y + inset);
      widget.setOriginalWidth(SIZE - 2 * inset);
      widget.setOriginalHeight(SIZE - 2 * inset);
    }
    icon.setSpriteId(SpriteID.SKILL_FARMING);
    button.setAction(0, "View Ultimate Farming items");
    button.setName("<col=ff9040>Ultimate Farming</col>");
    button.setHasListener(true);
    button.setNoClickThrough(true);
    button.setOnMouseOverListener(
        (JavaScriptCallback) ev -> button.setSpriteId(SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED));
    button.setOnMouseLeaveListener((JavaScriptCallback) ev -> style());
    button.setOnOpListener((JavaScriptCallback) ev -> toggleFilter());
    style();
    button.revalidate();
    icon.revalidate();
  }

  private void toggleFilter() {
    if (filterOpen()) bankTags.closeBankTag();
    else {
      // A fixed layout keeps every slot: a withdrawn item leaves a placeholder instead of the
      // rest shifting left.
      layoutManager.saveLayout(new Layout(BANK_TAG, plugin.kit().bankLayout()));
      bankTags.openBankTag(BANK_TAG, 0);
    }
    style();
  }

  /** The button stays pressed while the farming items are shown. */
  private void style() {
    if (button == null) return;
    button.setSpriteId(
        filterOpen()
            ? SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
            : SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL);
  }
}

package com.yonwi.farming;

/** A crop: its level, what's planted, its XP, its produce and the gardener's payment. */
final class Crop {
  final String name;
  final String sapling;
  final String fruit;
  final String payment;
  final int level;
  final int paymentQty;
  final double plant;
  final double check;
  final double harvest;

  Crop(
      String name,
      int level,
      String sapling,
      double plant,
      double check,
      double harvest,
      String fruit,
      String payment,
      int qty) {
    this.name = name;
    this.level = level;
    this.sapling = sapling;
    this.plant = plant;
    this.check = check;
    this.harvest = harvest;
    this.fruit = fruit;
    this.payment = payment;
    this.paymentQty = qty;
  }

  @Override
  public String toString() {
    return name;
  }
}

package com.yonwi.farming;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The debug setting's output: "[UF]" lines in RuneLite's client.log, and the last few detected
 * events for the debug box.
 */
final class DebugLog {
  private static final Logger LOG = LoggerFactory.getLogger(FarmingPlugin.class);
  private static final int EVENTS_KEPT = 4;
  private static final int EVENT_LENGTH = 40;

  @Inject private FarmingConfig config;

  private final Deque<String> events = new ArrayDeque<>();
  /** What each overlay highlighted last, so the log gets a line only when it changes. */
  private final Map<String, String> lastHighlights = new HashMap<>();
  /** Lines already logged by {@link #logOnce}. */
  private final Set<String> seen = new HashSet<>();
  /** The inventory overlay's last decision, shown in the debug box. */
  private volatile String overlayHint = "";

  /** With the debug setting on: a line in RuneLite's client.log, prefixed "[UF]". */
  void log(String text) {
    if (config.debug()) LOG.info("[UF] {}", text);
  }

  /** Logs a line the first time it comes up, and never again. */
  void logOnce(String line) {
    if (seen.add(line)) log(line);
  }

  /** Remembers the last few detected events for the debug box. */
  void event(String text) {
    String line = text.length() > EVENT_LENGTH ? text.substring(0, EVENT_LENGTH) + "…" : text;
    if (line.equals(events.peekFirst())) return;
    log("event: " + text);
    events.addFirst(line);
    while (events.size() > EVENTS_KEPT) events.removeLast();
  }

  Iterable<String> events() {
    return events;
  }

  /** Logs what an overlay highlights, and in which colour, whenever that changes. */
  void noteHighlights(String overlay, String what) {
    if (!config.debug() || what.equals(lastHighlights.get(overlay))) return;
    lastHighlights.put(overlay, what);
    log("highlights (" + overlay + "): " + (what.isEmpty() ? "none" : what));
  }

  void setOverlayHint(String hint) {
    overlayHint = hint;
  }

  String overlayHint() {
    return overlayHint;
  }
}

package com.yonwi.farming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
