  private void sendKitOrder() {
    if (kit == null) return;
    List<String> names = new ArrayList<>(kit.wear);
    List<String> bring = new ArrayList<>(kit.bring.keySet());
    bring.sort(Comparator.comparingInt(name -> name.endsWith("sapling") ? 0 : 1));
    names.addAll(bring);
    if (settings.level == 99 && !names.contains("Farming cape")) names.add("Farming cape");
    kitOrder.accept(names);
    // Worn items count too (one each), so the bank can tick them off as well.
    Map<String, Integer> counts = new LinkedHashMap<>();
    for (String worn : kit.wear) counts.put(worn, 1);
    counts.putAll(kit.bring);
    kitCounts.accept(counts);
  }

  // ---- Saved state ----

  /** Reads settings, records and any unfinished run from the active RuneLite profile. */
  private void loadState() {
    settings = load("settings", Settings.class, new Settings());
    sanitize();
    records = new ArrayList<>();
    RunRecord[] saved = load("records", RunRecord[].class, new RunRecord[0]);
    for (RunRecord record : saved)
      if (record != null && record.signature != null && record.milliseconds > 0) records.add(record);
    elapsed = 0;
    session = load("session", RunRecord.Session.class, null);
    if (session != null) {
      elapsed = Math.max(0, session.elapsed);
      if (session.signature == null) session = null;
    }
  }

  /**
   * The RuneLite profile changed. Everything in memory belongs to the old profile, so it's dropped
   * unsaved and the new profile's data is read instead. Saving first would copy the old profile's
   * records and settings over the new one's.
   */
  void reload() {
    if (disposed) return;
    running = false;
    prepared = false;
    skipBankCheck = false;
    runTab.reset();
    guideIndex = 0;
    phaseIndex = 0;
    setupTab.reset();
    recordsTab.reset();
    loadState();
    rebuild();
    updateTimer();
  }

  /** Fills in anything missing or out of range in saved settings, and upgrades old ones. */
  private void sanitize() {
    settings.level = Math.max(1, Math.min(99, settings.level));
    settings.herbYield = Double.isFinite(settings.herbYield) ? Math.max(0, Math.min(50, settings.herbYield)) : 8;
    settings.bark = Math.max(3, Math.min(100, settings.bark));
    if (settings.kinds == null) settings.kinds = new LinkedHashSet<>(Arrays.asList("tree", "fruit"));
    if (settings.unlocks == null) settings.unlocks = new LinkedHashSet<>();
    if (settings.crops == null) settings.crops = new LinkedHashMap<>();
    if (settings.excluded == null) settings.excluded = new LinkedHashSet<>();
    if (settings.completed == null) settings.completed = new LinkedHashSet<>();
    if (settings.progress == null) settings.progress = new LinkedHashMap<>();
    if (settings.order == null) settings.order = new ArrayList<>();
    if (settings.unprotected == null) settings.unprotected = new LinkedHashSet<>();
    if (settings.unharvested == null) settings.unharvested = new LinkedHashSet<>();
    // The old all-or-nothing switches become per-crop choices.
    if (!settings.protect) settings.unprotected.addAll(FarmingData.CROPS.keySet());
    if (!settings.harvest) settings.unharvested.addAll(FarmingData.CROPS.keySet());
    settings.protect = true;
    settings.harvest = true;
    if (settings.house == null) settings.house = "brimhaven";
  }

  private <T> T load(String key, Class<T> type, T fallback) {
    try {
      String value = config.getConfiguration(GROUP, key);
      T data = value == null ? null : gson.fromJson(value, type);
      return data == null ? fallback : data;
    } catch (RuntimeException ex) {
      return fallback;
    }
  }

  private void save() {
    config.setConfiguration(GROUP, "settings", gson.toJson(settings));
    if (session == null) config.unsetConfiguration(GROUP, "session");
    else {
      session.elapsed = duration();
      config.setConfiguration(GROUP, "session", gson.toJson(session));
    }
  }

  // ---- What the plugin reports ----

  void updateLevel(int level) {
    clientLevel = level;
    if (session == null && settings.level != level) {
      settings.level = level;
      rebuild();
      save();
    } else runTab.render(); // just refresh the "Farming level" line
  }

  void updateXp(long xp) {
    farmingXp = xp;
  }

  /** Applies unlocks read from the account. Waits for the run to end before changing the route. */
  void updateAccount(AccountScan.Result result) {
    account = result;
    missingChanged.accept(toWithdraw());
    if (session != null) {
      kitTab.render();
      return;
    }
    if (applyUnlocks(result)) {
      save();
      rebuild();
      return;
    }
    kitTab.render();
    if (setupTab.showsTravel()) setupTab.render(); // the Travel page lists what was detected
    // Re-checks the bank-first step as items are withdrawn.
    updateGuide();
  }

  /** Copies the account's Magic level, unlocks and house into the settings; true if any changed. */
  private boolean applyUnlocks(AccountScan.Result result) {
    boolean changed = false;
    if (result.magic > 0 && settings.magic != result.magic) {
      settings.magic = result.magic;
      changed = true;
    }
    for (Map.Entry<String, Boolean> unlock : result.unlocks.entrySet())
      changed |=
          unlock.getValue() ? settings.unlocks.add(unlock.getKey()) : settings.unlocks.remove(unlock.getKey());
    if (result.house != null && !result.house.equals(settings.house)) {
      settings.house = result.house;
      changed = true;
    }
    return changed;
  }

  /**
   * Records an in-game planting, compost or gardener payment. The patch completes once every
   * required action has been seen.
   */
  void patchAction(String action, String kind, Set<String> nearby) {
    FarmingPlanner.Step target = patchActedOn(action, kind, nearby);
    if (target == null) return;
    int at = route.indexOf(target);
    // A health check at the guided patch is read from the patch itself once it has happened.
    if (action.equals("Check health") && at == guideIndex) return;
    // Acting at a different route patch means you've moved on: guide that one from here. The
    // patch you left counts as finished once it was planted (or you'd come back to it later).
    if (guideIndex < route.size() && at != guideIndex && nearby.contains(target.patch.id)) {
      String left = route.get(guideIndex).patch.id;
      if (settings.progress.getOrDefault(left, Collections.emptySet()).contains("Plant"))
        settings.completed.add(left);
      guideIndex = at;
      phaseIndex = 0;
    }
    record(target, action);
  }

  /** The unfinished route patch an action was seen at: one you're beside, else the guided one. */
  private FarmingPlanner.Step patchActedOn(String action, String kind, Set<String> nearby) {
    List<FarmingPlanner.Step> candidates = new ArrayList<>();
    if (guideIndex < route.size()) candidates.add(route.get(guideIndex));
    candidates.addAll(route);
    for (FarmingPlanner.Step step : candidates) {
      if (settings.completed.contains(step.patch.id)) continue;
      if (kind != null && !kind.equals(step.patch.kind)) continue;
      if (!Guidance.phases(step, settings).contains(action)) continue;
      if (nearby.contains(step.patch.id)
          || nearby.isEmpty() && guideIndex < route.size() && step == route.get(guideIndex)) return step;
    }
    return null;
  }

  /** Marks a step as done at a patch, moves the guide past it, and finishes the patch if due. */
  private void record(FarmingPlanner.Step target, String action) {
    Set<String> seen = settings.progress.computeIfAbsent(target.patch.id, k -> new LinkedHashSet<>());
    seen.add(action);
    if (action.equals("Plant")) settings.plantedAt.put(target.patch.id, System.currentTimeMillis());
    List<String> phases = Guidance.phases(target, settings);
    boolean done = true;
    for (String phase : FINISHING) done &= !phases.contains(phase) || seen.contains(phase);
    if (done) settings.completed.add(target.patch.id);
    // Composting the empty patch before planting is fine, but the guide stays on clearing and
    // planting; once planted it skips past the compost already done.
    boolean early = action.equals("Compost") && phases.contains("Plant") && !seen.contains("Plant");
    if (!early && guideIndex < route.size() && route.get(guideIndex) == target) {
      int at = phases.indexOf(action);
      for (String phase : seen) at = Math.max(at, phases.indexOf(phase));
      phaseIndex = Math.max(phaseIndex, Math.min(at + 1, phases.size() - 1));
    }
    if (done) phaseIndex = 0;
    // The timer starts itself once the first patch of a fresh run is finished.
    if (done && settings.autoStart && session == null && target == route.get(0)) startRun(true);
    else save();
    // Finishing the last patch, e.g. composting the final herb patch, ends the timed run.
    if (done && session != null && allPatchesDone()) {
      finishRun();
      return;
    }
    runTab.render();
    updateGuide();
  }

  private boolean allPatchesDone() {
    return route.stream().allMatch(step -> settings.completed.contains(step.patch.id));
  }

  /** A route teleport was used: the run is under way, whatever the kit now lacks. */
  void setOff() {
    if (skipBankCheck || !prepared) return;
    skipBankCheck = true;
    updateGuide();
  }

  /**
   * Resurrect Crops brought a dead patch back: it keeps growing, so there's nothing to pick,
   * plant or compost there this run. The patch is finished.
   */
  void resurrected(String patchId) {
    FarmingPlanner.Step target = null;
    for (FarmingPlanner.Step step : route) if (step.patch.id.equals(patchId)) target = step;
    if (target == null || settings.completed.contains(patchId)) return;
    settings.completed.add(patchId);
    settings.progress.remove(patchId);
    if (guideIndex < route.size() && route.get(guideIndex) == target) phaseIndex = 0;
    save();
    if (session != null && allPatchesDone()) {
      finishRun();
      return;
    }
    runTab.render();
    updateGuide();
  }

  /** Celastrus bark chopped at the route's Celastrus patch, for the run's real profit. */
  void barkChopped(int amount) {
    if (session != null) session.bark += amount;
  }

  /** Herb runs start timing on the first herb picked at an unfinished route patch. */
  void herbPicked(Set<String> nearby, int picked) {
    if (session != null) {
      session.herbs += picked;
      return;
    }
    if (!settings.autoStart) return;
    for (int i = 0; i < route.size(); i++) {
      String id = route.get(i).patch.id;
      if (nearby.contains(id) && !settings.completed.contains(id)) {
        guideIndex = i;
        List<String> phases = Guidance.phases(route.get(i), settings);
        phaseIndex = Math.max(0, phases.indexOf("Harvest"));
        startRun(true);
        session.herbs += picked;
        updateGuide();
        return;
      }
    }
  }

  /** The plugin saw a step finish in-game; move the guide on if it is still on that step. */
  void phaseDone(String patchId, String phase) {
    if (guideIndex >= route.size() || !route.get(guideIndex).patch.id.equals(patchId)) return;
    List<String> phases = Guidance.phases(route.get(guideIndex), settings);
    if (phaseIndex >= phases.size() || !phases.get(phaseIndex).equals(phase)) return;
    // Planting and the final noting also count towards finishing the patch.
    if (FINISHING.contains(phase)) {
      record(route.get(guideIndex), phase);
      return;
    }
    phaseIndex = Math.min(phaseIndex + 1, phases.size() - 1);
    // Tree runs start timing on their first health check.
    if (phase.equals("Check health") && settings.autoStart && session == null) startRun(true);
    updateGuide();
  }

  private void clearProgress() {
    settings.completed.clear();
    settings.progress.clear();
  }

  // ---- The kit check ----

  /**
   * Kit items you aren't carrying or wearing, with how many are short. Pouch runes are checked
   * inside the rune pouch. Empty while logged out.
   */
  private List<String> missing() {
    List<String> result = new ArrayList<>();
    if (account == null || kit == null || route.isEmpty()) return result;
    Map<String, Integer> needed = new LinkedHashMap<>();
    for (String worn : kit.wear) needed.put(worn, 1);
    needed.putAll(kit.bring);
    for (Map.Entry<String, Integer> item : needed.entrySet()) addShortfall(result, item.getKey(), item.getValue());
    // Teleport spells in the route only work from the standard spellbook.
    boolean spells = route.stream().anyMatch(step -> Guidance.spell(step.travel) != null);
    if (spells && account.spellbook != 0) result.add(SWITCH_STANDARD);
    if (settings.resurrects(route) && account.spellbook != ARCEUUS) result.add(SWITCH_ARCEUUS);
    // Spellbook switched with the magic cape: it goes back in the bank (it isn't kit).
    if (!result.contains(SWITCH_ARCEUUS) && !result.contains(SWITCH_STANDARD))
      for (int id : FarmingData.IDS.get("Magic cape"))
        if (account.carried.getOrDefault(id, 0) > 0) {
          result.add(DEPOSIT_CAPE);
          break;
        }
    return result;
  }

  /** Adds a line for one kit item if you're carrying fewer than the run needs. */
  private void addShortfall(List<String> result, String name, int want) {
    int[] ids = FarmingData.IDS.get(name);
    if (ids == null) return;
    // An empty bottomless bucket doesn't count: it needs filling with compost first.
    if (name.equals("Bottomless compost bucket")) {
      ids = new int[] {FarmingData.id(name)};
      name = "Filled bottomless compost bucket";
    }
    // Runes count wherever they are: in the rune pouch, the inventory, or both.
    boolean rune = name.endsWith(" rune");
    int have = 0;
    for (int id : ids) {
      have += account.carried.getOrDefault(id, 0);
      if (rune) have += account.pouch.getOrDefault(id, 0);
    }
    if (have >= want) return;
    // Coins aren't counted out: just say to bring some, or more once you're short.
    if (name.equals("Coins")) result.add(have == 0 ? "Coins" : "More coins (" + String.format("%,d", want) + " needed)");
    else result.add(name + (want - have > 1 ? " ×" + (want - have) : ""));
  }

  /** Before a run starts, the guide stays at the bank until the whole kit is carried. */
  private boolean preparing() {
    // Only once "Prepare run" is pressed: between runs the overlay stays out of the way.
    return prepared
        && !skipBankCheck
        && session == null
        && settings.completed.isEmpty()
        && settings.progress.isEmpty()
        // Under way (e.g. landed at the first patch, its ring now out of charges): no going back.
        && guideIndex == 0
        && phaseIndex == 0
        && !missing().isEmpty();
  }

  /** What still needs withdrawing, only while preparing; supplies run down during a run. */
  private List<String> toWithdraw() {
    return preparing() ? missing() : Collections.emptyList();
  }

  // ---- Drawing ----

  private void rebuild() {
    if (disposed) return;
    route = FarmingPlanner.plan(settings);
    kit = FarmingPlanner.kit(route, settings);
    kitChanged.accept(FarmingPlanner.itemIds(kit, settings));
    sendKitOrder();
    missingChanged.accept(toWithdraw());
    runTab.render();
    kitTab.render();
    setupTab.render();
    recordsTab.render();
    updateYield();
    updateGuide();
    revalidate();
    repaint();
  }

  /** Redraws the banner, e.g. after Net XP/GP is switched on or off. */
  void refreshBanner() {
    updateYield();
  }

  private String yieldText(String xp, String gp) {
    String text = "<html>Expected XP: " + xp + "<br>Expected GP: " + gp;
    // Optional: everything your recorded runs have made so far.
    if ("true".equals(config.getConfiguration(GROUP, "netTotals"))) {
      long netXp = 0;
      long netGp = 0;
      for (RunRecord record : records) {
        netXp += record.xp;
        if (record.profit != null) netGp += record.profit;
      }
      text += "<br>Net XP: " + number(netXp) + "<br>Net GP: " + (netGp >= 0 ? "+" : "−") + number(Math.abs(netGp));
    }
    return text + "</html>";
  }

  /** The banner's expected XP now, and expected GP once guide prices are read. */
  private void updateYield() {
    yield.setForeground(Style.INK);
    yield.setText(yieldText(number(FarmingPlanner.xp(route, settings)), "loading"));
    yield.setToolTipText(
        "Guide prices. Saplings, protection, compost and removal minus harvested fruit and bark."
            + " Travel charges excluded.");
    List<FarmingPlanner.Step> snapshot = new ArrayList<>(route);
    Settings snapshotSettings = gson.fromJson(gson.toJson(settings), Settings.class);
    double xp = FarmingPlanner.xp(snapshot, snapshotSettings);
    clientThread.invoke(
        () -> {
          if (disposed) return;
          Long net = FarmingPlanner.net(snapshot, snapshotSettings, this::guidePrice);
          SwingUtilities.invokeLater(
              () -> {
                if (disposed || !snapshot.equals(route)) return;
                String gp = net == null ? "unavailable" : (net >= 0 ? "+" : "−") + number(Math.abs(net));
                yield.setText(yieldText(number(xp), gp));
              });
        });
  }

  /** An item's guide price by name, or 0. Client thread. */
  private long guidePrice(String name) {
    int id = FarmingData.id(name);
    return id == 0 ? 0 : items.getItemPrice(id);
  }

  // ---- The guide ----

  /** Works out what to guide now and tells the plugin; redraws the guide card. */
  private void updateGuide() {
    if (disposed) return;
    // Prepared but nothing done yet: the bank button is wanted until the first step of the run.
    preparingChanged.accept(
        prepared && session == null && settings.completed.isEmpty() && settings.progress.isEmpty());
    skipFinishedPatches();
    if (guideIndex >= route.size() || route.isEmpty()) {
      guideChanged.accept(null);
      guideCard.showMessage(route.isEmpty() ? "No route selected" : "All patches checked");
    } else if (!prepared && session == null) {
      // Nothing is guided or highlighted until you choose to start preparing a run.
      guideChanged.accept(null);
      missingChanged.accept(Collections.emptyList());
      Crop growing = settings.crop(route.get(0).patch.kind);
      guideCard.showNextRun(idleMessage(), growing == null ? null : growing.sapling, this::prepare);
    } else showStepOrBank();
    runTab.render();
  }

  /** Off a finished patch: on to the first one not yet done. */
  private void skipFinishedPatches() {
    if (guideIndex >= route.size()) guideIndex = 0;
    if (route.isEmpty() || !settings.completed.contains(route.get(guideIndex).patch.id)) return;
    guideIndex = 0;
    while (guideIndex < route.size() && settings.completed.contains(route.get(guideIndex).patch.id)) guideIndex++;
    phaseIndex = 0;
  }

  private void showStepOrBank() {
    List<String> withdraw = toWithdraw();
    missingChanged.accept(withdraw);
    if (!withdraw.isEmpty()) {
      // Bank first: no teleport is guided or highlighted until the kit is carried.
      guideChanged.accept(null);
      guideCard.showWithdraw(withdraw, this::setOffAnyway);
      return;
    }
    FarmingPlanner.Step step = route.get(guideIndex);
    List<String> phases = Guidance.phases(step, settings);
    phaseIndex = Math.max(0, Math.min(phaseIndex, phases.size() - 1));
    Guidance guide = guidanceFor(step, phases.get(phaseIndex));
    guideChanged.accept(guide);
    guideCard.showStep(guide, route.size(), () -> movePhase(-1), () -> movePhase(1), () -> markPatchDone(step));
  }

  /** Everything the plugin needs about the guided step, the one before and the one after. */
  private Guidance guidanceFor(FarmingPlanner.Step step, String phase) {
    Guidance guide = new Guidance(step, settings, guideIndex + 1, route.size(), phase);
    boolean cape = FarmingPlanner.farmingCapeWorn(route, settings);
    guide.herbsPerPatch = herbCount(FarmingPlanner.expectedHerbs(step.patch, settings, cape));
    guide.herbsIfAlive = herbCount(FarmingPlanner.expectedHerbsIfAlive(step.patch, settings, cape));
    if (guideIndex > 0) {
      guide.prevPatchId = route.get(guideIndex - 1).patch.id;
      guide.prevKind = route.get(guideIndex - 1).patch.kind;
    }
    guide.resurrect = settings.resurrects(route);
    for (int next = guideIndex + 1; next < route.size(); next++)
      if (!settings.completed.contains(route.get(next).patch.id)) {
        setNextPatch(guide, route.get(next), cape);
        break;
      }
    return guide;
  }

  private void setNextPatch(Guidance guide, FarmingPlanner.Step next, boolean cape) {
    guide.nextDestination = next.patch.name;
    guide.nextTravel = next.travel.text;
    guide.nextPatchId = next.patch.id;
    guide.nextKind = next.patch.kind;
    guide.nextHerbsIfAlive = herbCount(FarmingPlanner.expectedHerbsIfAlive(next.patch, settings, cape));
    // Its teleport item, to show in orange (not the staff or pouch: nothing to click there).
    List<String> teleport = new ArrayList<>(next.travel.items);
    teleport.addAll(next.travel.gear);
    teleport.removeIf(item -> item.contains("staff") || item.equals("Rune pouch"));
    guide.nextTravelItems = teleport;
  }

  /** Expected herbs rounded up, or 8 when unknown. */
  private static int herbCount(double expected) {
    int count = (int) Math.ceil(expected);
    return count <= 0 ? 8 : count;
  }

  private void prepare() {
    prepared = true;
    updateGuide();
  }

  private void setOffAnyway() {
    skipBankCheck = true;
    updateGuide();
  }

  private void movePhase(int by) {
    phaseIndex += by;
    updateGuide();
  }

  private void markPatchDone(FarmingPlanner.Step step) {
    settings.completed.add(step.patch.id);
    phaseIndex = 0;
    save();
    runTab.render();
    updateGuide();
  }

  // ---- The timed run ----

  private long duration() {
    return elapsed + (running ? (System.nanoTime() - nanoStart) / 1_000_000 : 0);
  }

  private void startRun(boolean keepProgress) {
    if (route.isEmpty()) return;
    prepared = true;
    if (session == null) {
      session = newSession();
      if (!keepProgress) {
        clearProgress();
        guideIndex = 0;
        phaseIndex = 0;
      }
      elapsed = 0;
      runTab.render();
      setupTab.render();
      updateGuide();
    }
    if (!running) {
      nanoStart = System.nanoTime();
      running = true;
    }
    tabs.setSelectedIndex(RUN_TAB);
    save();
    updateTimer();
  }

  private RunRecord.Session newSession() {
    RunRecord.Session started = new RunRecord.Session();
    started.startXp = farmingXp;
    started.signature = FarmingPlanner.signature(route, kit, settings);
    started.label =
        String.join(" + ", settings.kinds) + " · " + route.size() + " patches · "
            + (settings.farmer ? "Farmer" : "Graceful");
    started.setup =
        String.join(", ", kit.wear)
            + ". "
            + (settings.unprotected.isEmpty()
                ? "Gardener protection"
                : "No protection for " + String.join(", ", settings.unprotected))
            + ", "
            + (settings.unharvested.isEmpty()
                ? "harvesting"
                : "not harvesting " + String.join(", ", settings.unharvested))
            + ", "
            + (settings.bucket ? "bottomless bucket" : "loose ultracompost");
    started.patches = route.size();
    return started;
  }

  private void pauseOrResume() {
    if (running) pauseRun();
    else if (session != null) {
      running = true;
      nanoStart = System.nanoTime();
      updateTimer();
    }
  }

  private void pauseRun() {
    if (!running) return;
    elapsed = duration();
    running = false;
    save();
    updateTimer();
  }

  private void finishRun() {
    if (session == null || duration() < SHORTEST_RUN_MS) return;
    RunRecord record = new RunRecord();
    record.signature = session.signature;
    record.label = session.label;
    record.setup = session.setup;
    record.date = Instant.now().toString();
    record.milliseconds = duration();
    record.patches = session.patches;
    record.completed = (int) route.stream().filter(step -> settings.completed.contains(step.patch.id)).count();
    record.herbs = session.herbs;
    record.bark = session.bark;
    if (session.startXp > 0 && farmingXp > session.startXp) record.xp = farmingXp - session.startXp;
    records.add(record);
    if (records.size() > MAX_RECORDS) records.remove(0);
    recordsTab.showLatest(record);
    saveRecords();
    priceRecord(record);
    resetRun();
    recordsTab.render();
    tabs.setSelectedIndex(RECORDS_TAB);
    onFinish.run();
  }

  /** Profit at guide prices for the patches done, using the herbs actually picked. */
  private void priceRecord(RunRecord record) {
    List<FarmingPlanner.Step> done = new ArrayList<>();
    for (FarmingPlanner.Step step : route) if (settings.completed.contains(step.patch.id)) done.add(step);
    Settings priced = gson.fromJson(gson.toJson(settings), Settings.class);
    long herbPatches = done.stream().filter(step -> step.patch.kind.equals("herb")).count();
    if (herbPatches > 0) priced.herbActual = (double) record.herbs / herbPatches;
    // Celastrus bark actually chopped this run, when counted.
    if (record.bark > 0) priced.bark = record.bark;
    clientThread.invoke(
        () -> {
          Long profit = FarmingPlanner.net(done, priced, this::guidePrice);
          SwingUtilities.invokeLater(
              () -> {
                record.profit = profit;
                saveRecords();
                recordsTab.render();
              });
        });
  }

  private void resetRun() {
    running = false;
    elapsed = 0;
    session = null;
    skipBankCheck = false;
    prepared = false;
    clearProgress();
    guideIndex = 0;
    phaseIndex = 0;
    save();
    if (account != null) updateAccount(account);
    rebuild();
    updateTimer();
  }

  private void updateTimer() {
    clock.setText(time(duration()));
    timeChanged.accept(session == null ? null : time(duration()));
    // Keep the between-runs overlay line current, e.g. once the plants are grown.
    idleChanged.accept(idleMessage());
    start.setEnabled(!running && !route.isEmpty());
    pause.setEnabled(session != null);
    pause.setText(running || session == null ? "Pause" : "Resume");
    finish.setEnabled(session != null && duration() >= SHORTEST_RUN_MS);
    // Also after Prepare run, before anything has started: back to between runs.
    reset.setEnabled(prepared || session != null || !settings.completed.isEmpty() || !settings.progress.isEmpty());
    reset.setToolTipText("Abandon this run: clears its progress and timer without saving a time");
  }

  /**
   * Between runs: when this route's crops will all be grown. From what RuneLite's Time Tracking
   * last saw at each patch, else the planting time this plugin saw (patches planted before either
   * was watching have neither). Null if nothing is known.
   */
  private String idleMessage() {
    if (prepared || session != null) return null;
    long ready = 0;
    for (FarmingPlanner.Step step : route) {
      Long at = TimeTrackingData.readyAt(config, step.patch.id);
      Long planted = settings.plantedAt.get(step.patch.id);
      Crop crop = settings.crop(step.patch.kind);
      if (at == null && planted != null && crop != null) at = FarmingData.readyAt(crop.name, planted);
      if (at != null) ready = Math.max(ready, at);
    }
    if (ready == 0) return null;
    if (ready <= System.currentTimeMillis()) return "Your patches be ready!";
    String at =
        LocalDateTime.ofInstant(Instant.ofEpochMilli(ready), ZoneId.systemDefault())
            .format(DateTimeFormatter.ofPattern("HH:mm"));
    return "The plants still be growin' - come back at " + at;
  }

  void dispose() {
    guideChanged.accept(null);
    disposed = true;
    pauseRun();
    ticker.stop();
    save();
  }
}

package com.yonwi.farming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.ToLongFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Plans a run: which patches, in what order and how to get to each, what to wear and bring, and
 * what it's expected to make.
 */
final class FarmingPlanner {
  private static final Pattern FAIRY_CODE = Pattern.compile("Fairy ring ([A-Z]{3})");
  private static final Pattern CHARTER_TO = Pattern.compile("charter to ([a-z' ]+?)(;|,| then|$)");

  /** One way to travel: its text, rough cost in minutes, and items carried and worn. */
  static final class Choice {
    final String text;
    final double cost;
    final List<String> items;
    final List<String> gear;

    Choice(String text, double cost, List<String> items, List<String> gear) {
      this.text = text;
      this.cost = cost;
      this.items = items;
      this.gear = gear;
    }
  }

  /** One patch of the run and how to get there. */
  static final class Step {
    final Patch patch;
    final Choice travel;
    boolean noteBefore;
    boolean noteAfter = true;

    Step(Patch patch, Choice travel) {
      this.patch = patch;
      this.travel = travel;
    }
  }

  /** What to wear, and what to bring with how many of each. */
  static final class Kit {
    final List<String> wear = new ArrayList<>();
    final Map<String, Integer> bring = new LinkedHashMap<>();

    void add(String name, int quantity) {
      bring.merge(name, quantity, Integer::sum);
    }
  }

  private FarmingPlanner() {}

  /** A spirit tree in the house: every spirit tree trip starts there. */
  static boolean houseTree(Settings settings) {
    return settings.poh() && settings.has("spirit");
  }

  /** The three-letter fairy ring code in a travel line, or null. */
  static String fairyCode(String travel) {
    Matcher code = FAIRY_CODE.matcher(travel);
    return code.find() ? code.group(1) : null;
  }

  /** The port in a travel line's "charter to …", lower case, or null. */
  static String charterPort(String travel) {
    Matcher port = CHARTER_TO.matcher(travel.toLowerCase(Locale.ROOT));
    return port.find() ? port.group(1).trim() : null;
  }

  /** Ways to get to a patch, the quickest first. */
  static List<Choice> choices(Patch patch, Settings settings) {
    return TravelChoices.forPatch(patch, settings);
  }

  /** Travel between two patches: a walk or boat between them if quicker, else the second's own quickest. */
  private static Choice edge(List<Patch> patches, List<Choice> direct, int from, int to, Settings settings) {
    Choice between = TravelChoices.between(patches.get(from), patches.get(to), settings);
    return between != null && between.cost < direct.get(to).cost ? between : direct.get(to);
  }

  static List<Step> plan(Settings settings) {
    return reorder(suggested(settings), settings);
  }

  /** Applies the player's chosen order, recalculating travel between neighbouring patches. */
  static List<Step> reorder(List<Step> route, Settings settings) {
    if (settings.order == null || settings.order.isEmpty()) return route;
    List<Step> sorted = new ArrayList<>(route);
    sorted.sort(
        Comparator.comparingInt(
            step -> settings.order.contains(step.patch.id) ? settings.order.indexOf(step.patch.id) : Integer.MAX_VALUE));
    List<Step> result = new ArrayList<>();
    for (int i = 0; i < sorted.size(); i++) {
      Patch patch = sorted.get(i).patch;
      Choice direct = choices(patch, settings).get(0);
      Choice between = i == 0 ? null : TravelChoices.between(sorted.get(i - 1).patch, patch, settings);
      result.add(new Step(patch, between != null && between.cost < direct.cost ? between : direct));
    }
    setNoting(result);
    return result;
  }

  /**
   * The plugin's own order: patches linked by a walk or boat are grouped, and each group is visited
   * in its quickest order. Herb runs keep the patch list's order.
   */
  static List<Step> suggested(Settings settings) {
    List<Patch> patches = new ArrayList<>();
    List<Choice> direct = new ArrayList<>();
    for (Patch patch : FarmingData.PATCHES)
      if (TravelChoices.reachable(patch, settings)) {
        List<Choice> ways = choices(patch, settings);
        if (!ways.isEmpty()) {
          patches.add(patch);
          direct.add(ways.get(0));
        }
      }
    List<Step> result = new ArrayList<>();
    if (settings.kinds.size() == 1 && settings.kinds.contains("herb")) {
      for (int i = 0; i < patches.size(); i++) result.add(new Step(patches.get(i), direct.get(i)));
      setNoting(result);
      return result;
    }
    Set<Integer> unseen = new LinkedHashSet<>();
    for (int i = 0; i < patches.size(); i++) unseen.add(i);
    while (!unseen.isEmpty()) {
      List<Integer> group = linkedGroup(unseen, patches, direct, settings);
      List<Integer> order = quickestOrder(group, patches, direct, settings);
      for (int i = 0; i < order.size(); i++) {
        int at = order.get(i);
        result.add(new Step(patches.get(at), i == 0 ? direct.get(at) : edge(patches, direct, order.get(i - 1), at, settings)));
      }
    }
    setNoting(result);
    return result;
  }

  /** The first unseen patch and every patch linked to it by a quicker walk or boat (removed from unseen). */
  private static List<Integer> linkedGroup(
      Set<Integer> unseen, List<Patch> patches, List<Choice> direct, Settings settings) {
    List<Integer> group = new ArrayList<>();
    int first = unseen.iterator().next();
    group.add(first);
    unseen.remove(first);
    for (int i = 0; i < group.size(); i++)
      for (int j : new ArrayList<>(unseen))
        if (edge(patches, direct, group.get(i), j, settings) != direct.get(j)
            || edge(patches, direct, j, group.get(i), settings) != direct.get(group.get(i))) {
          group.add(j);
          unseen.remove(j);
        }
    return group;
  }

  /** The group's patches in their quickest order (every order tried, as a bitmask shortest path). */
  private static List<Integer> quickestOrder(
      List<Integer> group, List<Patch> patches, List<Choice> direct, Settings settings) {
    int size = group.size();
    int full = (1 << size) - 1;
    double[][] cost = new double[full + 1][size];
    int[][] parent = new int[full + 1][size];
    for (int visited = 0; visited <= full; visited++) {
      Arrays.fill(cost[visited], Double.POSITIVE_INFINITY);
      Arrays.fill(parent[visited], -1);
    }
    for (int j = 0; j < size; j++) cost[1 << j][j] = direct.get(group.get(j)).cost;
    for (int visited = 1; visited <= full; visited++)
      for (int i = 0; i < size; i++)
        if ((visited & (1 << i)) != 0)
          for (int j = 0; j < size; j++)
            if ((visited & (1 << j)) == 0) {
              int next = visited | (1 << j);
              double total = cost[visited][i] + edge(patches, direct, group.get(i), group.get(j), settings).cost;
              if (total < cost[next][j]) {
                cost[next][j] = total;
                parent[next][j] = i;
              }
            }
    int end = 0;
    for (int i = 1; i < size; i++) if (cost[full][i] < cost[full][end]) end = i;
    int visited = full;
    List<Integer> order = new ArrayList<>();
    while (end >= 0) {
      order.add(group.get(end));
      int previous = parent[visited][end];
      visited ^= 1 << end;
      end = previous;
    }
    Collections.reverse(order);
    return order;
  }

  /** Herb runs have no noting steps: the player notes herbs whenever suits them. */
  static void setNoting(List<Step> route) {
    for (Step step : route) {
      step.noteBefore = false;
      step.noteAfter = false;
    }
  }

  /** The kit name for a travel item, e.g. "Boat fare" is coins and tablets are by teleport name. */
  static String normalize(String name) {
    if (name.equals("Boat fare") || name.equals("Coins for tree removal")) return "Coins";
    if (name.endsWith(" tablets")) return name.substring(0, name.length() - 8);
    if (name.equals("Civitas illa Fortis teleport tablet")) return "Civitas illa Fortis teleport";
    if (name.equals("Dramen/lunar staff if required")) return "Dramen or lunar staff";
    return name;
  }

  /** The equipment slot an item is worn in, from its name, or "" if it isn't worn. */
  static String slot(String name) {
    String lower = name.toLowerCase(Locale.ROOT);
    if (lower.contains("hat") || lower.contains("hood")) return "head";
    if (lower.contains("cape")) return "cape";
    if (lower.contains("necklace") || lower.contains("pendant") || lower.contains("talisman")) return "neck";
    if (lower.contains("staff") || lower.contains("secateurs")) return "weapon";
    if (lower.contains("jacket") || lower.contains(" top")) return "body";
    if (lower.contains("trousers") || lower.contains(" legs")) return "legs";
    if (lower.contains("gloves")) return "hands";
    if (lower.contains("boots")) return "feet";
    if (lower.contains("ring")) return "ring";
    return "";
  }

  private static boolean hasKind(List<Step> route, String kind) {
    return route.stream().anyMatch(step -> step.patch.kind.equals(kind));
  }

  /** What to wear and bring for a route. */
  static Kit kit(List<Step> route, Settings settings) {
    Kit kit = new Kit();
    if (route.isEmpty()) return kit;
    addGear(kit, route, settings);
    kit.add("Spade", 1);
    kit.add("Rake", 1);
    int compost = 0;
    int removal = 0;
    for (Step step : route) {
      Crop crop = settings.crop(step.patch.kind);
      kit.add(crop.sapling, 1);
      if (settings.pays(step.patch)) kit.add(crop.payment, crop.paymentQty);
      if (settings.composts(step.patch)) compost++;
      removal += removalCost(step.patch);
      addTravelItems(kit, step);
    }
    boolean herbs = hasKind(route, "herb");
    if (herbs) kit.add("Seed dibber", 1);
    // An owned herb sack comes along: open, it takes the herbs before the inventory does.
    if (settings.has("herbSack") && herbs) kit.bring.put("Herb sack", 1);
    if (removal > 0) kit.add("Coins", removal);
    if (compost > 0) kit.add(settings.bucket ? "Bottomless compost bucket" : "Ultracompost", settings.bucket ? 1 : compost);
    if (hasKind(route, "celastrus")) kit.add("Axe", 1);
    addRunes(kit, route, settings);
    if (settings.stamina && route.size() > 5) kit.add("Stamina potion(4)", 1);
    return kit;
  }

  /** The outfit and worn travel items, one per slot; anything else worn-type goes in the bag. */
  private static void addGear(Kit kit, List<Step> route, Settings settings) {
    Set<String> occupied = new HashSet<>();
    Set<String> gear = new LinkedHashSet<>();
    // The farming cape is worn first (+5% herbs, and it still teleports); a Construction cape
    // then rides in the inventory, where its Tele to POH still works.
    boolean farmingCape = settings.level >= 99 && settings.has("farmingCape");
    if (farmingCape) gear.add("Farming cape");
    for (Step step : route) gear.addAll(step.travel.gear);
    if (settings.secateurs && hasKind(route, "herb")) gear.add("Magic secateurs");
    gear.addAll(
        settings.farmer
            ? Arrays.asList("Farmer's strawhat", "Farmer's jacket", "Farmer's boro trousers", "Farmer's boots")
            : Arrays.asList(
                "Graceful hood", "Graceful cape", "Graceful top", "Graceful legs", "Graceful gloves", "Graceful boots"));
    for (String raw : gear) {
      String name = normalize(raw);
      String slot = slot(name);
      if (farmingCape && name.equals("Graceful cape")) continue; // the cape slot is taken
      if (!slot.isEmpty() && occupied.add(slot)) kit.wear.add(name);
      else kit.add(name, 1);
    }
  }

  private static void addTravelItems(Kit kit, Step step) {
    for (String raw : step.travel.items) {
      String name = normalize(raw);
      if (kit.wear.contains(name)) continue; // already worn, e.g. the farming cape
      if (name.equals("Coins")) kit.bring.put(name, Math.max(10000, kit.bring.getOrDefault(name, 0)));
      else if (name.endsWith("teleport")) kit.add(name, 1);
      else kit.bring.put(name, 1);
    }
  }

  /**
   * The pouch carries the standard teleport runes when the route casts them, otherwise the
   * Resurrect Crops runes (earth runes ride loose: the pouch holds 3 types).
   */
  private static void addRunes(Kit kit, List<Step> route, Settings settings) {
    if (settings.has("pouch") && Settings.usesSpells(route)) {
      kit.bring.put("Rune pouch", 1);
      kit.bring.put("Law rune", 1);
      kit.bring.put("Lava rune", 1);
      kit.bring.put("Mist rune", 1);
    } else if (settings.resurrects(route)) {
      if (settings.has("pouch")) kit.bring.put("Rune pouch", 1);
      // Enough for 2 casts: covers 2 dead patches (about 1 run in 19 has 2; 3+ is 1 in 180).
      for (String[] rune : RESURRECT_RUNES) kit.bring.put(rune[0], 2 * Integer.parseInt(rune[1]));
    }
  }

  /** Coins the gardener charges to remove the old tree. */
  static int removalCost(Patch patch) {
    if (patch.kind.equals("redwood")) return 2000;
    return Arrays.asList("calquat", "celastrus", "herb").contains(patch.kind) ? 0 : 200;
  }

  // ---- Herb yield, from the OSRS wiki's herb calculator (Module:Herb_Farming_calculator) ----

  /** Each herb's chance to save a harvest life at level 1, out of 256; it's 80 at level 99. */
  private static final Map<String, Integer> HERB_LOW_CTS = new HashMap<>();

  static {
    String[] names = {
      "Guam", "Marrentill", "Tarromin", "Harralander", "Ranarr", "Toadflax", "Irit", "Avantoe",
      "Kwuarm", "Snapdragon", "Cadantine", "Lantadyme", "Dwarf weed", "Torstol"
    };
    int[] low = {25, 28, 31, 36, 39, 43, 46, 50, 54, 57, 60, 64, 67, 71};
    for (int i = 0; i < names.length; i++) HERB_LOW_CTS.put(names[i], low[i]);
  }

  private static final int HERB_HIGH_CTS = 80;

  /** Harvest lives with ultracompost: 3 base + 3 from the compost. */
  private static final int ULTRACOMPOST_LIVES = 6;

  /** Chance to die per growth stage with ultracompost: (floor(27 / 10) + 1) / 128. */
  private static final double ULTRACOMPOST_DEATH_PER_STAGE = (27 / 10 + 1) / 128.0;

  /** Runes for one Resurrect Crops cast. */
  static final String[][] RESURRECT_RUNES = {
    {"Soul rune", "8"}, {"Nature rune", "12"}, {"Blood rune", "8"}, {"Earth rune", "25"}
  };

  /** Herb patches that can't get diseased, always or with the given unlock. */
  private static boolean diseaseFree(Patch patch, Settings settings) {
    switch (patch.id) {
      case "herbtroll": // My Arm's Big Adventure
      case "herbweiss": // Fire of Nourishment
      case "herbharmony": // Morytania elite diary
        return true;
      case "herbhosidius":
        return settings.has("kourendEasy");
      case "herbfortis":
        return settings.has("fortisGlory");
      default:
        return false;
    }
  }

  /** Chance the herbs survive to harvest: (1 - P)^3, or 1 on a disease-free patch. */
  static double herbSurvival(Patch patch, Settings settings) {
    return herbSurvival(patch, settings, false);
  }

  /**
   * With Resurrect Crops, the wiki's death chance is
   * (1-(1-P)^4)(1-R) + 6P²(1-P)² + 4P³(1-P) + P⁴, R being the spell's success chance.
   */
  static double herbSurvival(Patch patch, Settings settings, boolean resurrect) {
    if (diseaseFree(patch, settings)) return 1;
    double p = ULTRACOMPOST_DEATH_PER_STAGE;
    if (!resurrect) return Math.pow(1 - p, 3);
    double r = resurrectChance(settings.magic);
    double death =
        (1 - Math.pow(1 - p, 4)) * (1 - r) + 6 * p * p * Math.pow(1 - p, 2) + 4 * Math.pow(p, 3) * (1 - p) + Math.pow(p, 4);
    return 1 - death;
  }

  /** Resurrect Crops success: 50% at 78 Magic to 75% at 99 (wiki: interpolate -111 to 191). */
  static double resurrectChance(int magic) {
    int level = Math.max(1, Math.min(99, magic));
    double value = (int) (-111 * (99 - level) / 98.0) + (int) (191 * (level - 1) / 98.0) + 1;
    return Math.min(Math.max(value / 256, 0), 1);
  }

  /** Diary yield bonus as a flat addition to the chance to save (5% = 10, 10% = 17, 15% = 25). */
  private static int diaryBonus(Patch patch, Settings settings) {
    if ((patch.id.equals("herbhosidius") || patch.id.equals("herbguild")) && settings.has("kourendHard")) return 10;
    if (patch.id.equals("herbcatherby")) {
      if (settings.has("kandarinElite")) return 25;
      if (settings.has("kandarinHard")) return 17;
      if (settings.has("kandarinMedium")) return 10;
    }
    return 0;
  }

  /** Whether the farming cape (+5% yield) is worn: 99 Farming, owned, and the cape slot is free. */
  static boolean farmingCapeWorn(List<Step> route, Settings settings) {
    if (settings.level < 99 || !settings.has("farmingCape")) return false;
    for (String worn : kit(route, settings).wear)
      if (slot(worn).equals("cape") && !worn.equals("Farming cape")) return false;
    return true;
  }

  /**
   * Expected herbs from one patch, dead patches included, exactly as the wiki calculator works it
   * out: chance to save interpolated between level 1 and 99 values (after item and diary bonuses),
   * harvest lives / (1 - chance to save), times the chance the patch survives.
   */
  static double expectedHerbs(Patch patch, Settings settings, boolean capeWorn) {
    return expectedHerbs(patch, settings, capeWorn, false);
  }

  static double expectedHerbs(Patch patch, Settings settings, boolean capeWorn, boolean resurrect) {
    Crop crop = settings.crop(patch.kind);
    Integer low = crop == null ? null : HERB_LOW_CTS.get(crop.name);
    if (low == null) return 0;
    double itemBonus = (settings.secateurs ? .1 : 0) + (capeWorn ? .05 : 0);
    int diary = diaryBonus(patch, settings);
    // An Attas plant at the Farming Guild multiplies the chance to save by 1.05.
    double attas = settings.has("attas") ? .05 : 0;
    int lowFinal = (int) Math.floor(((int) Math.floor(low * (1 + itemBonus)) + diary) * (1 + attas));
    int highFinal = (int) Math.floor(((int) Math.floor(HERB_HIGH_CTS * (1 + itemBonus)) + diary) * (1 + attas));
    int level = Math.max(1, Math.min(99, settings.level));
    // Module:Skilling success chart: truncated interpolation, + 1, out of 256.
    double value = (int) (lowFinal * (99 - level) / 98.0) + (int) (highFinal * (level - 1) / 98.0) + 1;
    double chanceToSave = Math.min(Math.max(value / 256, 0), 1);
    double yield = chanceToSave >= 1 ? 0 : ULTRACOMPOST_LIVES / (1 - chanceToSave);
    return yield * herbSurvival(patch, settings, resurrect);
  }

  /** Expected herbs from one patch that survives to harvest. */
  static double expectedHerbsIfAlive(Patch patch, Settings settings, boolean capeWorn) {
    double survival = herbSurvival(patch, settings, false);
    return survival <= 0 ? 0 : expectedHerbs(patch, settings, capeWorn, false) / survival;
  }

  /** Farming XP the run is expected to give. */
  static double xp(List<Step> route, Settings settings) {
    double total = 0;
    boolean cape = farmingCapeWorn(route, settings);
    boolean resurrect = settings.resurrects(route);
    for (Step step : route) {
      Crop crop = settings.crop(step.patch.kind);
      if (step.patch.kind.equals("herb")) {
        // As the wiki: herbs picked plus planting when the patch survives; no compost XP.
        total +=
            expectedHerbs(step.patch, settings, cape, resurrect) * crop.harvest
                + crop.plant * herbSurvival(step.patch, settings, resurrect);
        continue;
      }
      double harvest =
          !settings.harvests(step.patch.kind)
              ? 0
              : step.patch.kind.equals("celastrus") ? bark(settings) * 23.5 : crop.harvest;
      total += crop.plant + crop.check + harvest;
    }
    return total * (settings.farmer ? 1.025 : 1);
  }

  /**
   * GP the run is expected to make at these prices: produce minus saplings, payments, compost,
   * removal and (with Resurrect Crops) runes. Null if a price is missing.
   */
  static Long net(List<Step> route, Settings settings, ToLongFunction<String> price) {
    long net = 0;
    boolean cape = farmingCapeWorn(route, settings);
    boolean resurrect = settings.resurrects(route);
    long castCost = 0;
    if (resurrect)
      for (String[] rune : RESURRECT_RUNES) {
        long each = price.applyAsLong(rune[0]);
        if (each <= 0) return null;
        castCost += each * Integer.parseInt(rune[1]);
      }
    for (Step step : route) {
      // Rune cost × the patch's death chance with resurrect, as the wiki calculator charges it.
      if (resurrect && step.patch.kind.equals("herb"))
        net -= Math.round(castCost * (1 - herbSurvival(step.patch, settings, true)));
      Long patchNet = patchNet(step, settings, price, cape, resurrect);
      if (patchNet == null) return null;
      net += patchNet;
    }
    return net;
  }

  /** One patch's produce minus its costs, or null if a price is missing. */
  private static Long patchNet(
      Step step, Settings settings, ToLongFunction<String> price, boolean cape, boolean resurrect) {
    Crop crop = settings.crop(step.patch.kind);
    long net = 0;
    long sapling = price.applyAsLong(crop.sapling);
    if (sapling <= 0) return null;
    net -= sapling;
    net -= removalCost(step.patch);
    if (settings.pays(step.patch)) {
      long payment = price.applyAsLong(crop.payment);
      if (payment <= 0) return null;
      net -= payment * crop.paymentQty;
    }
    if (settings.composts(step.patch)) {
      long compost = price.applyAsLong("Ultracompost");
      if (compost <= 0) return null;
      net -= settings.bucket ? compost / 2 : compost;
    }
    String harvest = step.patch.kind.equals("celastrus") ? "Celastrus bark" : crop.fruit;
    if (!harvest.isEmpty() && settings.harvests(step.patch.kind)) {
      long value = price.applyAsLong(harvest);
      if (value <= 0 && !harvest.equals("Calquat fruit")) return null;
      double herbs =
          settings.herbActual != null
              ? Math.max(0, settings.herbActual) // a finished run's real average
              : expectedHerbs(step.patch, settings, cape, resurrect);
      double amount =
          step.patch.kind.equals("herb") ? herbs : step.patch.kind.equals("celastrus") ? bark(settings) : 6;
      net += Math.round(value * amount);
    }
    return net;
  }

  /** Every item ID for the kit, including charged variants, for bank tags and the bank view. */
  static Set<Integer> itemIds(Kit kit, Settings settings) {
    Set<Integer> ids = new LinkedHashSet<>();
    List<String> items = new ArrayList<>(kit.wear);
    items.addAll(kit.bring.keySet());
    if (settings.level == 99) items.add("Farming cape");
    for (String name : items) for (int id : FarmingData.IDS.getOrDefault(name, new int[0])) ids.add(id);
    return ids;
  }

  /** A Bank Tags import string for the kit. */
  static String tags(Kit kit, Settings settings) {
    StringBuilder tags = new StringBuilder("Ultimate Farming");
    for (int id : itemIds(kit, settings)) tags.append(',').append(id);
    return tags.toString();
  }

  /** The item pictured beside a travel line in the Run tab. */
  static String travelItem(Choice travel, Settings settings) {
    String text = travel.text.toLowerCase(Locale.ROOT);
    if (text.startsWith("walk") || text.startsWith("run ")) return "Graceful boots";
    if (text.contains("spirit tree")) return "Spirit sapling";
    if (text.contains("farming cape")) return "Farming cape";
    if (text.contains("construction cape")) return "Construction cape";
    if (!travel.items.isEmpty()) return normalize(travel.items.get(0));
    if (!travel.gear.isEmpty()) return normalize(travel.gear.get(0));
    return "Spade";
  }

  /** Identifies a run's setup, so records of the same run can be compared. */
  static String signature(List<Step> route, Kit kit, Settings settings) {
    List<String> parts = new ArrayList<>();
    for (Step step : route) parts.add(step.patch.id + ":" + step.travel.text);
    Collections.sort(parts);
    List<String> gear = new ArrayList<>(kit.wear);
    Collections.sort(gear);
    return String.join("|", parts)
        + "/" + gear
        + "/" + settings.farmer
        + "/" + settings.unprotected
        + "/" + settings.unharvested
        + "/" + settings.bucket
        + "/" + (hasKind(route, "celastrus") ? settings.level : 0);
  }

  /**
   * Celastrus bark per patch, worked out rather than asked for: the wiki's money making guide
   * expects 8.8 at 99 Farming (ultracompost, magic secateurs), and about 6 at 85. In between it
   * scales with level; Attas adds 5%.
   */
  static double bark(Settings settings) {
    double level = Math.max(85, Math.min(99, settings.level));
    double bark = 6 + 2.8 * (level - 85) / 14;
    if (!settings.secateurs) bark /= 1.1;
    if (settings.has("attas")) bark *= 1.05;
    return bark;
  }
}

