package com.yonwi.farming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** Everything the plugin needs to guide one step of the run: where, what to do and with what. */
final class Guidance {
  final String patchId;
  final String destination;
  final String kind;
  final String travel;
  final String action;
  final String phase;
  /** Every action at this patch in order, and which one is being guided. */
  final List<String> phases;
  /** Specific wording for each substep, e.g. "Plant Ranarr seed". */
  final List<String> labels = new ArrayList<>();

  final int phaseIndex;
  /** Standard spellbook teleport to cast while travelling, or null. */
  final String spell;
  final int step;
  final int total;
  final List<String> items;
  /** The substep after this one and its items, highlighted in a second colour; null at the end. */
  final String nextPhase;

  final List<String> nextItems;
  /** Expected herbs from one patch, to judge whether the inventory has room for the next. */
  int herbsPerPatch = 8;
  /** Expected herbs here if the patch is alive, for judging whether they'll fit. */
  int herbsIfAlive = 8;
  /** The stage before this one (its patch and kind), or null for the first. */
  String prevPatchId;
  String prevKind;
  /** The next patch's teleport item(s), shown in orange during this patch's last step. */
  List<String> nextTravelItems = Collections.emptyList();
  /** What a harvest here gives, unnoted ("Celastrus bark", "Coconut"…); empty for none or herbs. */
  String produce = "";
  /** Dead herbs here should get Resurrect Crops before anything else. */
  boolean resurrect;
  /** The patch after this one and how to get there, for the "Next up" line; null at the end. */
  String nextDestination;
  String nextTravel;
  /** The next stage's patch and kind, and its expected herbs if alive (for noting before leaving). */
  String nextPatchId;
  String nextKind;
  int nextHerbsIfAlive = 8;

  Guidance(FarmingPlanner.Step at, Settings setup, int step, int total, String phase) {
    this(at, setup, step, total, phase, true);
  }

  private Guidance(
      FarmingPlanner.Step at, Settings setup, int step, int total, String phase, boolean withNext) {
    patchId = at.patch.id;
    destination = at.patch.name;
    kind = at.patch.kind;
    travel = at.travel.text;
    this.step = step;
    this.total = total;
    this.phase = phase;
    phases = phases(at, setup);
    phaseIndex = Math.max(0, phases.indexOf(phase));
    spell = spell(at.travel);
    for (String each : phases) labels.add(label(each, at, setup));
    Crop crop = setup.crop(kind);
    if (kind.equals("celastrus")) produce = "Celastrus bark";
    else if (crop != null && crop.fruit != null && !kind.equals("herb")) produce = crop.fruit;
    items = new ArrayList<>();
    switch (phase) {
      case "Travel":
        action = travel;
        items.addAll(at.travel.items);
        items.addAll(at.travel.gear);
        if (spell != null) items.remove("Rune pouch");
        break;
      case "Note carried":
        action = "Note carried herbs at the leprechaun before harvesting this patch.";
        items.add(crop.fruit);
        break;
      case "Check health":
        action = "Check the grown " + kind + " tree’s health.";
        break;
      case "Harvest":
        action =
            kind.equals("herb")
                ? "Harvest all herbs. If inventory fills, note here; otherwise carry to the next noting stop."
                : kind.equals("celastrus")
                    ? "Harvest Celastrus bark with an axe."
                    : "Pick all six fruit before clearing.";
        // (No axe highlight: it's used straight from the inventory.)
        if (kind.equals("herb") && setup.secateurs) items.add("Magic secateurs");
        break;
      case "Clear":
        action = "Clear the old tree and stump. Use the gardener where removal is available.";
        // Where the gardener removes the tree, only the gardener is needed.
        // Only the gardener or the patch is highlighted, never the spade or axe.
        break;
      case "Plant":
        action = "Rake if needed, then plant " + crop.sapling + ".";
        items.add(crop.sapling);
        items.add("Rake");
        break;
      case "Protect":
        action = "Pay gardener: " + crop.paymentQty + " " + crop.payment + ".";
        // Only the gardener is highlighted; the payment is handed over in the dialogue.
        break;
      case "Compost":
        action = "Apply ultracompost to the new crop.";
        items.add(setup.bucket ? "Bottomless compost bucket" : "Ultracompost");
        break;
      default:
        action = "Note harvested produce at the tool leprechaun if needed.";
        items.add(crop.fruit);
    }
    nextPhase =
        withNext && phaseIndex + 1 < phases.size() ? phases.get(phaseIndex + 1) : null;
    nextItems =
        nextPhase == null
            ? Collections.emptyList()
            : new Guidance(at, setup, step, total, nextPhase, false).items;
  }

  /** Every step at a patch, in order. */
  static List<String> phases(FarmingPlanner.Step step, Settings settings) {
    String kind = step.patch.kind;
    if (kind.equals("herb")) {
      List<String> herb = new ArrayList<>();
      herb.add("Travel");
      if (step.noteBefore) herb.add("Note carried");
      herb.addAll(Arrays.asList("Harvest", "Plant", "Compost"));
      if (step.noteAfter) herb.add("Note harvest");
      return herb;
    }
    List<String> phases = new ArrayList<>(Arrays.asList("Travel", "Check health"));
    Crop crop = settings.crop(kind);
    boolean produce = settings.harvests(kind) && (kind.equals("celastrus") || !crop.fruit.isEmpty());
    if (produce) phases.add("Harvest");
    phases.add("Clear");
    phases.add("Plant");
    if (settings.pays(step.patch)) phases.add("Protect");
    if (settings.composts(step.patch)) phases.add("Compost");
    if (produce) phases.add("Note harvest");
    return phases;
  }

  /** The spell cast from the rune pouch for this travel choice, if any. */
  static String spell(FarmingPlanner.Choice travel) {
    if (!travel.items.contains("Rune pouch")) return null;
    for (String place : Arrays.asList("Falador", "Lumbridge", "Varrock", "Camelot", "Ardougne"))
      if (travel.text.startsWith("Cast " + place + " Teleport")) return place;
    return "House";
  }

  /** A step's specific wording, e.g. "Plant Ranarr seed". */
  static String label(String phase, FarmingPlanner.Step at, Settings setup) {
    String kind = at.patch.kind;
    Crop crop = setup.crop(kind);
    switch (phase) {
      case "Travel":
        return at.travel.text;
      case "Note carried":
        return "Note carried herbs at the leprechaun";
      case "Check health":
        return "Check the " + crop.name.toLowerCase(Locale.ROOT) + " tree's health";
      case "Harvest":
        if (kind.equals("herb")) return "Pick the " + crop.fruit.toLowerCase(Locale.ROOT).replace("grimy ", "");
        return kind.equals("celastrus") ? "Chop Celastrus bark" : "Pick 6 " + crop.fruit.toLowerCase(Locale.ROOT);
      case "Clear":
        return Targets.GARDENER_REMOVAL.contains(kind)
            ? "Pay the gardener to remove the tree"
            : kind.equals("celastrus")
                ? "Chop the tree down, then dig up the stump"
                : kind.equals("calquat")
                    ? "Dig up the bare tree with a spade"
                    : "Dig up the stump with a spade";
      case "Plant":
        return "Plant " + crop.sapling;
      case "Protect":
        return "Pay the gardener " + crop.paymentQty + " × " + crop.payment;
      case "Compost":
        return setup.bucket ? "Use the bottomless bucket (ultracompost)" : "Apply ultracompost";
      default:
        String produce = kind.equals("herb") ? "herbs" : crop.fruit.toLowerCase(Locale.ROOT);
        return "Note " + produce + " at the leprechaun";
    }
  }
}

package com.yonwi.farming;

import static com.yonwi.farming.PanelWidgets.CARD_TEXT;
import static com.yonwi.farming.PanelWidgets.column;
import static com.yonwi.farming.PanelWidgets.fixHeight;
import static com.yonwi.farming.PanelWidgets.html;
import static com.yonwi.farming.PanelWidgets.label;
import static com.yonwi.farming.PanelWidgets.muted;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The card at the top of the Run tab: the next run, what to withdraw, or the step to do now. */
final class GuideCard {
  private final ItemPictures pictures;
  private final JPanel card = Style.card();

  GuideCard(ItemPictures pictures) {
    this.pictures = pictures;
  }

  JPanel card() {
    return card;
  }

  /** Just a line, e.g. "All patches checked". */
  void showMessage(String text) {
    card.removeAll();
    card.add(muted(text));
    fixHeight(card);
  }

  /**
   * Between runs: nothing is guided or highlighted until you choose to start preparing a run. A
   * picture of what's growing beside the heading and when it'll be ready.
   */
  void showNextRun(String idle, String growingSapling, Runnable prepare) {
    card.removeAll();
    JLabel picture = new JLabel();
    picture.setPreferredSize(new Dimension(34, 32));
    if (growingSapling != null) pictures.small(picture, growingSapling, 34, 30);
    JPanel words = column();
    words.setOpaque(false);
    JLabel next = Style.section("Next run");
    next.setBorder(new EmptyBorder(0, 0, 3, 0));
    words.add(next);
    JLabel when =
        label(
            "<html><div style=\"width:" + (CARD_TEXT - 42) + "px\">"
                + html(idle == null ? "Press Prepare run when you're ready." : idle)
                + "</div></html>");
    when.setFont(Style.small());
    words.add(when);
    JPanel top = new JPanel(new BorderLayout(8, 0));
    top.setOpaque(false);
    top.add(picture, BorderLayout.WEST);
    top.add(words, BorderLayout.CENTER);
    top.setAlignmentX(Component.LEFT_ALIGNMENT);
    card.add(top);
    card.add(Box.createVerticalStrut(8));
    JButton button = Style.primary("Prepare run", null);
    button.setToolTipText("Show the bank kit check, guide and highlights for this run");
    button.addActionListener(e -> prepare.run());
    card.add(button);
    fixHeight(card);
  }

  /** Bank first: no teleport is guided or highlighted until the kit is carried. */
  void showWithdraw(List<String> withdraw, Runnable setOffAnyway) {
    card.removeAll();
    JLabel now = Style.section("Withdraw from the bank");
    now.setBorder(new EmptyBorder(0, 0, 3, 0));
    card.add(now);
    for (String item : withdraw) {
      JLabel line = muted("• " + item);
      line.setForeground(PanelWidgets.WARN);
      card.add(line);
    }
    card.add(Box.createVerticalStrut(6));
    JButton anyway = new JButton("Set off anyway");
    anyway.setToolTipText("Skip the kit check until this run is cleared");
    anyway.addActionListener(e -> setOffAnyway.run());
    card.add(anyway);
    fixHeight(card);
  }

  /** The step being guided, with Back, Next and Done. */
  void showStep(Guidance guide, int patches, Runnable back, Runnable next, Runnable done) {
    card.removeAll();
    JLabel now = Style.section("Now · patch " + guide.step + " of " + patches);
    now.setBorder(new EmptyBorder(0, 0, 3, 0));
    card.add(now);
    JLabel heading =
        label(
            "<html><div style=\"width:" + CARD_TEXT + "px\">"
                + html(guide.destination)
                // Travelling: the grey line below already says how to get there.
                + (guide.phase.equals("Travel") ? "" : " · " + html(guide.labels.get(guide.phaseIndex)))
                + "</div></html>");
    heading.setFont(Style.bold());
    card.add(heading);
    card.add(muted(guide.action));
    card.add(Box.createVerticalStrut(6));
    JPanel actions = new JPanel(new GridLayout(1, 3, 3, 0));
    actions.setOpaque(false);
    JButton backButton = new JButton("Back");
    JButton nextButton = new JButton("Next");
    JButton doneButton = new JButton("Done");
    backButton.setToolTipText("Previous action");
    nextButton.setToolTipText("Next action");
    doneButton.setToolTipText("Mark this patch complete and guide the next patch");
    backButton.setEnabled(guide.phaseIndex > 0);
    nextButton.setEnabled(guide.phaseIndex < guide.phases.size() - 1);
    backButton.addActionListener(e -> back.run());
    nextButton.addActionListener(e -> next.run());
    doneButton.addActionListener(e -> done.run());
    actions.add(backButton);
    actions.add(nextButton);
    actions.add(doneButton);
    fixHeight(actions);
    card.add(actions);
    fixHeight(card);
  }
}

package com.yonwi.farming;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

/** The guided stage's patch and gardener, found every tick, and what the patch shows. */
final class GuidedPatch {
  /** How far a gardener can be to count as this stage's. */
  private static final int GARDENER_RANGE = 32;

  @Inject private Client client;
  @Inject private FarmingPlugin plugin;

  /** The guided patch object, found each tick while nearby. */
  private TileObject object;
  private NPC gardener;
  /** Whether the guided patch currently offers "Rake", i.e. has weeds to clear. */
  private volatile boolean needsRake;
  /** The guided patch's crop has died and needs clearing before anything else. */
  private volatile boolean dead;

  TileObject object() {
    return object;
  }

  NPC gardener() {
    return gardener;
  }

  /** The guided patch has weeds: raking it is a single click on the patch. */
  boolean needsRake() {
    return needsRake;
  }

  boolean dead() {
    return dead;
  }

  void setDead(boolean dead) {
    this.dead = dead;
  }

  /** Finds the stage's patch every tick, so step completion can be read whatever is highlighted. */
  void find(Guidance step, Player player) {
    object = null;
    // The dead flag keeps the last reading until the progress check reads the patch again, so
    // the targets chosen this tick already know a dead crop is there.
    if (step == null || player == null) return;
    NPC nearbyGardener = findGardener(step, player);
    TileObject patch = step.kind.equals("herb") ? findHerbPatch(step) : findTreePatch(step);
    if (patch == null && !step.kind.equals("herb") && nearbyGardener != null)
      patch = findPatchByGardener(step, nearbyGardener);
    object = patch;
    if (patch == null) dead = false;
    gardener = nearbyGardener;
    needsRake = plugin.scene().offers(patch, "rake");
  }

  private NPC findGardener(Guidance step, Player player) {
    int gardenerId = TargetData.GARDENERS.getOrDefault(step.patchId, -1);
    for (NPC npc : plugin.scene().npcs())
      if (npc.getId() == gardenerId
          && npc.getWorldLocation().distanceTo(player.getWorldLocation()) <= GARDENER_RANGE)
        return npc;
    return null;
  }

  /** The farming object (one that changes with growth) at the herb patch's position. */
  private TileObject findHerbPatch(Guidance step) {
    WorldPoint at = TargetData.HERB_POINTS.get(step.patchId);
    if (at == null) return null;
    TileObject patch = null;
    int closest = 2;
    for (TileObject candidate : plugin.scene().objects()) {
      if (client.getObjectDefinition(candidate.getId()).getImpostorIds() == null) continue;
      int distance = candidate.getWorldLocation().distanceTo(at);
      if (distance < closest) {
        patch = candidate;
        closest = distance;
      }
    }
    return patch;
  }

  /**
   * Trees with a known position: the farming object there, found as soon as it's loaded and
   * whether or not there's a gardener (Summer Shore's Calquat has none).
   */
  private TileObject findTreePatch(Guidance step) {
    WorldPoint at = TargetData.PATCH_POINTS.get(step.patchId);
    if (at == null) return null;
    TileObject patch = null;
    int closest = 4;
    for (TileObject candidate : plugin.scene().objects()) {
      if (candidate.getPlane() != at.getPlane()) continue;
      int distance = candidate.getWorldLocation().distanceTo(at);
      if (distance >= closest) continue;
      ObjectComposition definition = client.getObjectDefinition(candidate.getId());
      if (definition == null || definition.getImpostorIds() == null) continue;
      definition = definition.getImpostor();
      if (definition == null || !TargetData.patchLike(definition, step.kind)) continue;
      patch = candidate;
      closest = distance;
    }
    return patch;
  }

  /** No known position: the patch-like object nearest the gardener. */
  private TileObject findPatchByGardener(Guidance step, NPC gardener) {
    TileObject patch = null;
    int closest = 15;
    for (TileObject candidate : plugin.scene().objects()) {
      int distance = candidate.getWorldLocation().distanceTo(gardener.getWorldLocation());
      if (distance > closest) continue;
      ObjectComposition definition = client.getObjectDefinition(candidate.getId());
      if (definition.getImpostorIds() != null) definition = definition.getImpostor();
      if (definition == null || !TargetData.patchLike(definition, step.kind)) continue;
      if (distance < closest) {
        patch = candidate;
        closest = distance;
      }
    }
    return patch;
  }
}

package com.yonwi.farming;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.gameval.ItemID;

/**
 * Counts what's picked: grimy herbs reaching the inventory or an open herb sack (which starts a
 * herb run's timer), and Celastrus bark chopped.
 */
final class HarvestTracker {
  static final int HERB_SACK_SIZE = 30;
  /**
   * Open herb sacks: picked grimy herbs go straight in, not into the inventory, up to 30 of each
   * herb (OSRS wiki; assumed the same for the silk sack).
   */
  private static final Set<Integer> OPEN_HERB_SACKS =
      new HashSet<>(Arrays.asList(ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SLAYER_HERB_SACK_SILK_OPEN));
  private static final Set<Integer> SHUT_HERB_SACKS =
      new HashSet<>(Arrays.asList(ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_SILK));
  /** Unnoted grimy herbs, whose count rising means a herb was just picked. */
  static final Set<Integer> GRIMY_HERBS = new HashSet<>();

  static {
    for (Crop crop : FarmingData.CROPS.get("herb"))
      for (int id : FarmingData.IDS.getOrDefault(crop.fruit, new int[0])) GRIMY_HERBS.add(id);
  }

  @Inject private Client client;
  @Inject private FarmingPlugin plugin;

  private int grimyCount = -1;
  private int barkCount = -1;
  /**
   * Herbs picked into the open sack since the bank was last open (where it's assumed emptied). It
   * can't be read from the game, so it's counted: Farming XP with no new grimy herb in the bag.
   */
  private int sackHerbs;
  private long farmingXp = -1;
  /** This tick: Farming XP went up, grimy herbs in the inventory went up. */
  private boolean xpGained;
  private boolean grimyGained;
  private boolean wasPickable;
  /** The herb patch you've started picking at (set by the first herb picked there). */
  private volatile String pickingPatch;
  /** Herbs picked at {@link #pickingPatch} so far. */
  private int pickedHere;

  static Set<Integer> shutHerbSacks() {
    return SHUT_HERB_SACKS;
  }

  String pickingPatch() {
    return pickingPatch;
  }

  /** Herbs picked so far at this patch, if it's the one being picked. */
  int pickedAt(String patchId) {
    return patchId.equals(pickingPatch) ? pickedHere : 0;
  }

  int sackHerbs() {
    return sackHerbs;
  }

  boolean holdingOpenSack() {
    return plugin.account().holdingUnnoted(OPEN_HERB_SACKS);
  }

  /** Logged out: counts start again from the next inventory seen. */
  void reset() {
    grimyCount = -1;
    farmingXp = -1;
  }

  /** The herb sack is emptied at the bank between runs (assumed; corrected once it's seen full). */
  void bankSeen() {
    sackHerbs = 0;
  }

  void farmingXpChanged(long xp) {
    if (farmingXp >= 0 && xp > farmingXp) xpGained = true;
    farmingXp = xp;
  }

  void inventoryChanged(ItemContainer inventory) {
    int count = 0;
    for (Item item : inventory.getItems())
      if (GRIMY_HERBS.contains(item.getId())) count += item.getQuantity();
    if (grimyCount >= 0 && count > grimyCount) {
      grimyGained = true;
      plugin.debug().event("herb picked: " + grimyCount + " -> " + count);
      herbPicked(count - grimyCount);
    }
    grimyCount = count;
    // Celastrus bark gained while guided at the Celastrus patch counts towards real profit.
    int bark = 0;
    for (Item item : inventory.getItems())
      if (item.getId() == ItemID.CELASTRUS_WOOD) bark += item.getQuantity();
    Guidance step = plugin.guide();
    if (barkCount >= 0 && bark > barkCount && step != null && step.kind.equals("celastrus")) {
      int gained = bark - barkCount;
      plugin.debug().event("bark chopped: +" + gained);
      plugin.toPanel(panel -> panel.barkChopped(gained));
    }
    barkCount = bark;
  }

  /**
   * A herb picked into an open herb sack never reaches the inventory, so it's spotted as Farming XP
   * with no new grimy herb while the guided herb patch offers Pick (this tick or last, as the last
   * herb empties it). It counts as picked, so the run timer starts and the herb is recorded. A herb
   * reaching the inventory with the sack open means the sack is full.
   */
  void countSackHerbs() {
    boolean xp = xpGained;
    boolean grimy = grimyGained;
    xpGained = false;
    grimyGained = false;
    boolean pickable = plugin.scene().offers(plugin.patch().object(), "pick");
    boolean was = wasPickable;
    wasPickable = pickable;
    Guidance step = plugin.guide();
    if (!xp || !(pickable || was) || step == null || !step.kind.equals("herb") || !holdingOpenSack())
      return;
    if (grimy) {
      if (sackHerbs < HERB_SACK_SIZE) plugin.debug().event("herb sack full");
      sackHerbs = HERB_SACK_SIZE;
      return;
    }
    if (sackHerbs < HERB_SACK_SIZE) sackHerbs++;
    plugin.debug().event("herb into sack: " + sackHerbs + "/" + HERB_SACK_SIZE);
    herbPicked(1);
  }

  /** Room left in an open herb sack carried in the inventory (0 without one). */
  int sackRoom() {
    return holdingOpenSack() ? Math.max(0, HERB_SACK_SIZE - sackHerbs) : 0;
  }

  /**
   * At a herb patch offering Pick with the herb sack carried shut (none open) and not yet full:
   * open it first, so the herbs go in it instead of the inventory.
   */
  boolean openSackNow() {
    Guidance step = plugin.guide();
    return step != null
        && step.kind.equals("herb")
        && step.phase.equals("Harvest")
        && wasPickable
        && !plugin.patch().dead()
        && sackHerbs < HERB_SACK_SIZE
        && plugin.account().holdingUnnoted(SHUT_HERB_SACKS)
        && !holdingOpenSack();
  }

  /** Picking a herb at a route patch starts a herb run's timer. */
  private void herbPicked(int picked) {
    Player player = client.getLocalPlayer();
    if (player == null) return;
    Set<String> nearby = new HashSet<>();
    int region = player.getWorldLocation().getRegionID();
    for (Map.Entry<String, Set<Integer>> entry : TargetData.HERB_REGIONS.entrySet())
      if (entry.getValue().contains(region)) nearby.add(entry.getKey());
    if (nearby.isEmpty()) return;
    // Picking has started here: from now on, noting is only suggested if the inventory fills.
    Guidance step = plugin.guide();
    if (step != null && nearby.contains(step.patchId)) {
      if (!step.patchId.equals(pickingPatch)) pickedHere = 0;
      pickingPatch = step.patchId;
      plugin.progress().setWorkedPatch(step.patchId);
      pickedHere += picked;
    }
    plugin.toPanel(panel -> panel.herbPicked(nearby, picked));
  }
}

package com.yonwi.farming;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.QuadCurve2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;

/** Small hand-drawn icons for the sidebar tabs and the Records stats, sized for the RS font. */
final class Icons {
  private static final Color INK = new Color(225, 225, 225);
  private static final Color GOLD = new Color(232, 186, 72);
  private static final Color GREEN = new Color(120, 200, 90);

  /** Icons are 16 × 16 pixels. */
  private static final int SIZE = 16;

  private Icons() {}

  /** The named icon (run, kit, setup, records, check…), or a blank one for an unknown name. */
  static ImageIcon get(String name) {
    BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = img.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    switch (name) {
      case "run": // a running figure
        g.setColor(INK);
        g.fill(new Ellipse2D.Double(9, 1, 3.6, 3.6));
        g.draw(new Line2D.Double(9.5, 5.5, 7.5, 10)); // body
        g.draw(new Line2D.Double(9, 6.5, 12.5, 8.5)); // front arm
        g.draw(new Line2D.Double(9, 6.5, 5.5, 7)); // back arm
        g.draw(new Line2D.Double(7.5, 10, 10.5, 12.5)); // front leg
        g.draw(new Line2D.Double(10.5, 12.5, 10, 15));
        g.draw(new Line2D.Double(7.5, 10, 5, 12.5)); // back leg
        g.draw(new Line2D.Double(5, 12.5, 2.5, 12.5));
        break;
      case "kit": // a backpack
        g.setColor(INK);
        g.draw(new RoundRectangle2D.Double(3, 4, 10, 11, 4, 4));
        g.draw(new Arc2D.Double(5.5, 1, 5, 5, 0, 180, Arc2D.OPEN));
        g.draw(new Line2D.Double(5.5, 9, 10.5, 9));
        break;
      case "setup": // a cog
        g.setColor(INK);
        for (int i = 0; i < 8; i++) {
          double angle = Math.PI * i / 4;
          g.draw(
              new Line2D.Double(
                  8 + 5 * Math.cos(angle), 8 + 5 * Math.sin(angle), 8 + 7 * Math.cos(angle),
                  8 + 7 * Math.sin(angle)));
        }
        g.draw(new Ellipse2D.Double(3.5, 3.5, 9, 9));
        g.draw(new Ellipse2D.Double(6.2, 6.2, 3.6, 3.6));
        break;
      case "records":
      case "runs": // bar chart
        g.setColor("records".equals(name) ? GOLD : INK);
        g.fill(new Rectangle2D.Double(2, 9, 3, 6));
        g.fill(new Rectangle2D.Double(6.5, 5, 3, 10));
        g.fill(new Rectangle2D.Double(11, 1.5, 3, 13.5));
        break;
      case "time": // clock
        g.setColor(INK);
        g.draw(new Ellipse2D.Double(1.5, 1.5, 13, 13));
        g.draw(new Line2D.Double(8, 8, 8, 4));
        g.draw(new Line2D.Double(8, 8, 11, 9.5));
        break;
      case "herbs": // leaf
        g.setColor(GREEN);
        Path2D leaf = new Path2D.Double();
        leaf.moveTo(2, 14);
        leaf.curveTo(1, 6, 6, 1.5, 14.5, 1.5);
        leaf.curveTo(14.5, 9, 10, 14.5, 2, 14);
        g.fill(leaf);
        g.setColor(new Color(40, 90, 40));
        g.draw(new Line2D.Double(2.5, 13.5, 12, 4));
        break;
      case "average": // sigma
        g.setColor(INK);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 15));
        g.drawString("Σ", 2, 14);
        break;
      case "profit": // stacked coins
        g.setColor(GOLD);
        for (int i = 0; i < 3; i++) {
          g.fill(new Ellipse2D.Double(2 + i * 2, 10 - i * 3.5, 9, 4.5));
          g.setColor(new Color(170, 125, 40));
          g.draw(new Ellipse2D.Double(2 + i * 2, 10 - i * 3.5, 9, 4.5));
          g.setColor(GOLD);
        }
        break;
      case "perRun": // one coin, face on (stacked coins are the total)
        g.setColor(GOLD);
        g.fill(new Ellipse2D.Double(2, 2, 12, 12));
        g.setColor(new Color(170, 125, 40));
        g.draw(new Ellipse2D.Double(2, 2, 12, 12));
        g.draw(new Ellipse2D.Double(5, 5, 6, 6));
        break;
      case "rate": // money sack
        g.setColor(new Color(190, 150, 90));
        g.fill(new Ellipse2D.Double(2, 5, 12, 10.5));
        g.fill(new Polygon(new int[] {5, 11, 9, 7}, new int[] {2, 2, 6, 6}, 4));
        g.setColor(new Color(110, 80, 40));
        g.draw(new Line2D.Double(5.5, 6, 10.5, 6));
        g.setColor(GOLD);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
        g.drawString("$", 6f, 13.5f);
        break;
      case "rank": // trophy
        g.setColor(GOLD);
        g.fill(new Arc2D.Double(3.5, -1, 9, 11, 180, 180, Arc2D.CHORD));
        g.draw(new Arc2D.Double(0.5, 2, 5, 5, 90, 180, Arc2D.OPEN));
        g.draw(new Arc2D.Double(10.5, 2, 5, 5, 270, 180, Arc2D.OPEN));
        g.fill(new Rectangle2D.Double(7, 9, 2, 3));
        g.fill(new Rectangle2D.Double(4.5, 12.5, 7, 2.5));
        break;
      case "check": // green tick in a filled circle
        g.setColor(new Color(76, 160, 76));
        g.fill(new Ellipse2D.Double(1, 1, 14, 14));
        g.setColor(Color.WHITE);
        g.setStroke(new BasicStroke(1.9f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(new Line2D.Double(4.5, 8.2, 7, 10.8));
        g.draw(new Line2D.Double(7, 10.8, 11.6, 5.4));
        break;
      case "chevron": // › pointing right
        g.setColor(new Color(150, 150, 150));
        g.draw(new Line2D.Double(6, 3.5, 10.5, 8));
        g.draw(new Line2D.Double(10.5, 8, 6, 12.5));
        break;
      case "play":
        g.setColor(Color.WHITE);
        g.fill(new Polygon(new int[] {4, 13, 4}, new int[] {2, 8, 14}, 3));
        break;
      case "pause":
        g.setColor(INK);
        g.fill(new Rectangle2D.Double(4, 3, 3, 10));
        g.fill(new Rectangle2D.Double(9.5, 3, 3, 10));
        break;
      case "flag":
        g.setColor(INK);
        g.draw(new Line2D.Double(3.5, 2, 3.5, 15));
        Path2D flag = new Path2D.Double();
        flag.moveTo(3.5, 2.5);
        flag.lineTo(13, 2.5);
        flag.lineTo(10.5, 5.5);
        flag.lineTo(13, 8.5);
        flag.lineTo(3.5, 8.5);
        g.draw(flag);
        break;
      case "noTime": // a clock struck through: the run's time doesn't count
        g.setColor(INK);
        g.draw(new Ellipse2D.Double(1.5, 1.5, 13, 13));
        g.draw(new Line2D.Double(8, 8, 8, 4));
        g.draw(new Line2D.Double(8, 8, 11, 9.5));
        g.setColor(new Color(230, 80, 70));
        g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(new Line2D.Double(2.5, 13.5, 13.5, 2.5));
        break;
      case "trash":
        g.setColor(INK);
        g.draw(new Line2D.Double(2.5, 4, 13.5, 4));
        g.draw(new Line2D.Double(6, 4, 6.5, 2));
        g.draw(new Line2D.Double(6.5, 2, 9.5, 2));
        g.draw(new Line2D.Double(9.5, 2, 10, 4));
        g.draw(new RoundRectangle2D.Double(4, 4, 8, 10.5, 2, 2));
        g.draw(new Line2D.Double(6.7, 6.5, 6.7, 12));
        g.draw(new Line2D.Double(9.3, 6.5, 9.3, 12));
        break;
      case "box": // unticked tickbox: light fill so it shows on the dark cards
        g.setColor(new Color(150, 152, 155));
        g.fill(new RoundRectangle2D.Double(1.5, 1.5, 13, 13, 3, 3));
        g.setColor(new Color(205, 207, 210));
        g.setStroke(new BasicStroke(1f));
        g.draw(new RoundRectangle2D.Double(1.5, 1.5, 13, 13, 3, 3));
        break;
      case "boxTicked": // ticked: gold with a dark tick
        g.setColor(GOLD);
        g.fill(new RoundRectangle2D.Double(1.5, 1.5, 13, 13, 3, 3));
        g.setColor(new Color(40, 30, 10));
        g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(new Line2D.Double(4.5, 8.2, 7, 10.8));
        g.draw(new Line2D.Double(7, 10.8, 11.6, 5.4));
        break;
      case "info": // ⓘ
        g.setColor(new Color(160, 160, 160));
        g.draw(new Ellipse2D.Double(1.5, 1.5, 13, 13));
        g.fill(new Ellipse2D.Double(7.1, 4, 1.8, 1.8));
        g.draw(new Line2D.Double(8, 7.5, 8, 11.5));
        break;
      default:
        break;
    }
    g.dispose();
    return new ImageIcon(img);
  }

  /** The same icon recoloured: every visible pixel takes {@code color}, keeping its opacity. */
  static ImageIcon tint(ImageIcon icon, Color color) {
    int width = icon.getIconWidth();
    int height = icon.getIconHeight();
    BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = img.createGraphics();
    g.drawImage(icon.getImage(), 0, 0, null);
    g.setComposite(AlphaComposite.SrcIn);
    g.setColor(color);
    g.fillRect(0, 0, width, height);
    g.dispose();
    return new ImageIcon(img);
  }

  /** A green leaf filling the whole 16px sidebar slot, corner to corner. */
  static BufferedImage leaf() {
    BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = icon.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
    Path2D leaf = new Path2D.Double();
    leaf.moveTo(1.5, 14.5);
    leaf.curveTo(0.5, 6, 6, 0.5, 15.5, 0.5);
    leaf.curveTo(15.5, 10, 10, 15.5, 1.5, 14.5);
    leaf.closePath();
    g.setPaint(new GradientPaint(2, 14, new Color(62, 132, 58), 14, 2, new Color(152, 214, 104)));
    g.fill(leaf);
    g.setColor(new Color(36, 84, 38));
    g.setStroke(new BasicStroke(0.9f));
    g.draw(leaf);
    g.setColor(new Color(214, 240, 170, 220));
    g.setStroke(new BasicStroke(1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    g.draw(new QuadCurve2D.Double(0.5, 15.5, 7, 9.5, 13.5, 2.5));
    g.dispose();
    return icon;
  }
}

package com.yonwi.farming;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import java.util.Map;

/** How much inventory a run's kit and harvest take, to keep a run within 28 slots. */
final class InventorySpace {
  static final int INVENTORY_SLOTS = 28;
  /** Runes kept in the rune pouch (it holds 3 types). */
  static final List<String> POUCH_RUNES =
      Arrays.asList("Law rune", "Lava rune", "Mist rune", "Soul rune", "Nature rune", "Blood rune");
  /** Fruit picked from one fruit tree or Calquat. */
  private static final int FRUIT_PER_TREE = 6;

  private InventorySpace() {}

  /**
   * How many squares an item takes in the Kit tab's Bring section: one per sapling or
   * ultracompost, none for runes kept in the rune pouch, one for anything else.
   */
  static int squares(String name, int quantity, Settings settings) {
    if (settings.has("pouch") && POUCH_RUNES.contains(name)) return 0;
    return name.endsWith("sapling") || name.equals("Ultracompost") ? quantity : 1;
  }

  /** Squares in the Kit tab's Bring section: the inventory space the run needs. */
  private static int bringSquares(FarmingPlanner.Kit kit, Settings settings) {
    int total = 0;
    for (Map.Entry<String, Integer> item : kit.bring.entrySet())
      total += squares(item.getKey(), item.getValue(), settings);
    return total;
  }

  /**
   * Free slots a harvest needs: the biggest single patch's produce (6 fruit or Calquat, the
   * expected Celastrus bark or herbs), as it's noted at the leprechaun before the next patch.
   * Nothing when nothing is harvested.
   */
  private static int harvestSquares(List<FarmingPlanner.Step> plan, Settings settings) {
    boolean cape = FarmingPlanner.farmingCapeWorn(plan, settings);
    int most = 0;
    for (FarmingPlanner.Step step : plan) {
      String kind = step.patch.kind;
      if (!settings.harvests(kind)) continue;
      int produce =
          kind.equals("herb")
              ? (int) Math.ceil(FarmingPlanner.expectedHerbs(step.patch, settings, cape))
              : kind.equals("celastrus")
                  ? (int) Math.round(FarmingPlanner.bark(settings))
                  : settings.crop(kind).fruit.isEmpty() ? 0 : FRUIT_PER_TREE;
      most = Math.max(most, produce);
    }
    return most;
  }

  /** Inventory space the run needs: the Bring section plus room for a patch's harvest. */
  static int needed(List<FarmingPlanner.Step> plan, FarmingPlanner.Kit kit, Settings settings) {
    return bringSquares(kit, settings) + harvestSquares(plan, settings);
  }

  /** Whether the run still fits in 28 inventory slots with this run type added. */
  static boolean fitsWith(Settings settings, String kind, Gson gson) {
    Settings copy = gson.fromJson(gson.toJson(settings), Settings.class);
    copy.kinds.add(kind);
    List<FarmingPlanner.Step> plan = FarmingPlanner.plan(copy);
    return needed(plan, FarmingPlanner.kit(plan, copy), copy) <= INVENTORY_SLOTS;
  }
}

package com.yonwi.farming;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/** Item pictures for the sidebar, loaded on the client thread and cached (Swing thread only). */
final class ItemPictures {
  private final ItemManager items;
  private final ClientThread clientThread;
  /** Everything the account owns, to show your own variant of an item; null when unknown. */
  private final Supplier<Set<Integer>> owned;
  private final BooleanSupplier disposed;
  /** Item pictures already loaded, by "id|width|height" or "id|full". */
  private final Map<String, Icon> cache = new HashMap<>();
  /** Item names by ID, for a variant's tooltip ("Infernal axe" rather than "Axe"). */
  private final Map<Integer, String> names = new HashMap<>();

  ItemPictures(ItemManager items, ClientThread clientThread, Supplier<Set<Integer>> owned, BooleanSupplier disposed) {
    this.items = items;
    this.clientThread = clientThread;
    this.owned = owned;
    this.disposed = disposed;
  }

  /** The picture to show for a kit item: your best variant of it (e.g. your infernal axe). */
  int shownId(String name) {
    return FarmingData.bestOwned(name, owned.get());
  }

  /** The item's full-size picture, with its name (or your variant's name) as the tooltip. */
  void full(JLabel target, String name) {
    int id = shownId(name);
    if (id == 0) {
      target.setText("•");
      target.setToolTipText(name);
      return;
    }
    target.setToolTipText(name);
    // A specific variant (your axe, your whistle): name it.
    if (id != FarmingData.id(name)) nameVariant(target, id);
    String key = id + "|full";
    Icon cached = cache.get(key);
    if (cached != null) {
      target.setIcon(cached); // no flicker on redraw
      return;
    }
    clientThread.invoke(
        () -> {
          if (disposed.getAsBoolean()) return;
          AsyncBufferedImage image = items.getImage(id);
          Runnable apply =
              () ->
                  SwingUtilities.invokeLater(
                      () -> {
                        ImageIcon icon = new ImageIcon(image);
                        target.setIcon(icon);
                        cache.put(key, icon);
                      });
          image.onLoaded(apply);
          apply.run();
        });
  }

  private void nameVariant(JLabel target, int id) {
    String known = names.get(id);
    if (known != null) {
      target.setToolTipText(known);
      return;
    }
    clientThread.invoke(
        () -> {
          String real = items.getItemComposition(id).getName();
          SwingUtilities.invokeLater(
              () -> {
                names.put(id, real);
                target.setToolTipText(real);
              });
        });
  }

  /** An item image scaled to fit, so it isn't cropped in small spaces. */
  void small(JLabel target, String name, int width, int height) {
    int id = shownId(name);
    if (id == 0) return;
    target.setToolTipText(name);
    // Already loaded once: set it now, so redrawing the tab doesn't make the pictures flicker.
    String key = id + "|" + width + "|" + height;
    Icon cached = cache.get(key);
    if (cached != null) {
      target.setIcon(cached);
      return;
    }
    clientThread.invoke(
        () -> {
          if (disposed.getAsBoolean()) return;
          AsyncBufferedImage image = items.getImage(id);
          Runnable apply =
              () ->
                  SwingUtilities.invokeLater(
                      () -> {
                        ImageIcon icon = new ImageIcon(ImageUtil.resizeImage(image, width, height, true));
                        target.setIcon(icon);
                        cache.put(key, icon);
                      });
          image.onLoaded(apply);
          apply.run();
        });
  }
}

package com.yonwi.farming;

import static com.yonwi.farming.PanelWidgets.addCard;
import static com.yonwi.farming.PanelWidgets.column;
import static com.yonwi.farming.PanelWidgets.html;
import static com.yonwi.farming.PanelWidgets.number;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.Box;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/** The Kit tab: what to wear (laid out like the equipment screen) and what to bring. */
final class KitTab {
  /** Equipment slots in the worn equipment screen's 3 × 5 layout ("" for a gap). */
  private static final String[] WORN_LAYOUT = {
    "", "head", "", "cape", "neck", "weapon", "", "body", "", "", "legs", "", "hands", "feet", "ring"
  };

  private final FarmingPanel panel;
  private final ItemManager items;
  private final ClientThread clientThread;
  private final JPanel page = column();

  KitTab(FarmingPanel panel, ItemManager items, ClientThread clientThread) {
    this.panel = panel;
    this.items = items;
    this.clientThread = clientThread;
  }

  JPanel page() {
    return page;
  }

  void render() {
    page.removeAll();
    page.add(Style.section("Wear"));
    addCard(page, wearCard());
    page.add(Style.section("Bring"));
    addCard(page, bringCard());
    page.add(Box.createVerticalGlue());
    page.revalidate();
  }

  private JPanel wearCard() {
    JPanel gear = new JPanel(new GridLayout(5, 3, 3, 3));
    gear.setOpaque(false);
    Map<String, String> slots = new HashMap<>();
    for (String name : panel.kit().wear) slots.put(FarmingPlanner.slot(name), name);
    for (String slot : WORN_LAYOUT) {
      JLabel cell = new JLabel();
      cell.setHorizontalAlignment(SwingConstants.CENTER);
      cell.setPreferredSize(new Dimension(40, 38));
      if (!slot.isEmpty()) {
        cell.setOpaque(true);
        cell.setBackground(Style.SELECT_BACKGROUND);
        String name = slots.get(slot);
        if (name != null) panel.pictures().full(cell, name);
      }
      gear.add(cell);
    }
    JPanel card = Style.card();
    card.add(gear);
    return card;
  }

  private JPanel bringCard() {
    JPanel inventory = new JPanel(new GridLayout(0, 4, 3, 3));
    inventory.setOpaque(false);
    List<Map.Entry<String, Integer>> entries = new ArrayList<>(panel.kit().bring.entrySet());
    entries.sort(Comparator.comparingInt(entry -> entry.getKey().endsWith("sapling") ? 0 : 1));
    for (Map.Entry<String, Integer> entry : entries) {
      String name = entry.getKey();
      int repeats = InventorySpace.squares(name, entry.getValue(), panel.settings());
      // (A pouch rune takes no square: it's shown on the pouch.)
      for (int i = 0; i < repeats; i++) inventory.add(bringCell(name, entry.getValue(), repeats));
    }
    JPanel card = Style.card();
    card.add(inventory);
    return card;
  }

  private JPanel bringCell(String name, int quantity, int repeats) {
    JPanel cell = new JPanel(new BorderLayout());
    cell.setOpaque(false);
    if (name.equals("Rune pouch")) cell.add(pouchIcon(cell), BorderLayout.CENTER);
    else {
      JLabel picture = new JLabel();
      picture.setHorizontalAlignment(SwingConstants.CENTER);
      panel.pictures().full(picture, name);
      cell.add(picture, BorderLayout.CENTER);
      cell.setToolTipText(name + " × " + quantity);
    }
    JLabel amount = new JLabel(repeats == 1 && quantity > 1 ? number(quantity) : " ");
    amount.setFont(Style.small());
    amount.setForeground(Style.MUTED);
    amount.setHorizontalAlignment(SwingConstants.CENTER);
    cell.add(amount, BorderLayout.SOUTH);
    cell.setPreferredSize(new Dimension(38, 46));
    return cell;
  }

  /**
   * The rune pouch with small icons of its runes drawn over it. Uses the pouch's real contents when
   * logged in, otherwise the runes the run needs. Hovering lists them.
   */
  private JComponent pouchIcon(JPanel cell) {
    AccountScan.Result account = panel.account();
    boolean known = account != null && !account.pouch.isEmpty();
    Map<Integer, Integer> runes = new LinkedHashMap<>();
    if (known) runes.putAll(account.pouch);
    else
      for (String rune : InventorySpace.POUCH_RUNES)
        if (panel.kit().bring.containsKey(rune)) runes.put(FarmingData.id(rune), 0);
    BufferedImage[] images = new BufferedImage[runes.size() + 1];
    JComponent icon =
        new JComponent() {
          @Override
          protected void paintComponent(Graphics g) {
            int x = (getWidth() - 36) / 2;
            int y = (getHeight() - 32) / 2;
            if (images[0] != null) g.drawImage(images[0], x, y, null);
            // Runes in rows of three across the bottom of the pouch, at about a third of full size.
            for (int i = 1; i < images.length; i++)
              if (images[i] != null)
                g.drawImage(images[i], x + (i - 1) % 3 * 12, y + 20 - (i - 1) / 3 * 11, 14, 12, null);
          }
        };
    icon.setPreferredSize(new Dimension(36, 32));
    List<Integer> ids = new ArrayList<>();
    ids.add(panel.pictures().shownId("Rune pouch"));
    ids.addAll(runes.keySet());
    clientThread.invoke(
        () -> {
          if (panel.isDisposed()) return;
          List<String> named = new ArrayList<>();
          for (int i = 0; i < ids.size(); i++) {
            AsyncBufferedImage image = items.getImage(ids.get(i));
            images[i] = image;
            image.onLoaded(icon::repaint);
            if (i > 0) {
              int amount = runes.get(ids.get(i));
              named.add(
                  html(items.getItemComposition(ids.get(i)).getName())
                      + (amount > 0 ? " × " + number(amount) : ""));
            }
          }
          AccountScan.Result now = panel.account();
          boolean real = now != null && !now.pouch.isEmpty();
          String tip =
              "<html>Rune pouch" + (real ? "" : " (needs)") + "<br>" + String.join("<br>", named) + "</html>";
          SwingUtilities.invokeLater(
              () -> {
                cell.setToolTipText(tip);
                icon.repaint();
              });
        });
    return icon;
  }
}

package com.yonwi.farming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * The run's kit (from the sidebar): what it needs, what's still to withdraw, the rune pouch, and
 * the bank filter's layout.
 */
final class KitTracker {
  private static final int[][] POUCH_SLOTS = {
    {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_QUANTITY_1},
    {VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_QUANTITY_2},
    {VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_QUANTITY_3},
    {VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_QUANTITY_4},
    {VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_QUANTITY_5},
    {VarbitID.RUNE_POUCH_TYPE_6, VarbitID.RUNE_POUCH_QUANTITY_6}
  };
  private static final Set<Integer> DIVINE_POUCHES =
      new HashSet<>(Arrays.asList(ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER));
  /** Slots in the bank's first row, the outfit you put on. */
  private static final int FIRST_ROW = 8;

  @Inject private Client client;
  @Inject private ItemManager itemManager;
  @Inject private FarmingPlugin plugin;

  /** Kit item names in Kit tab order (wear, then bring), for the bank layout. */
  private volatile List<String> order = Collections.emptyList();
  private volatile Map<String, Integer> counts = Collections.emptyMap();
  /** Every item ID the kit can use, for the bank filter. */
  private volatile Set<Integer> items = Collections.emptySet();
  private volatile List<String> missing = Collections.emptyList();
  /** Spare variants kept out of the bank filter, e.g. a basic whistle when you own a better one. */
  private volatile Set<Integer> hiddenVariants = Collections.emptySet();
  /** One line telling you what to do with the rune pouch at the bank, or null. */
  private volatile String pouchHint;

  /** Sets the kit order, returning whether it changed. */
  boolean setOrder(List<String> names) {
    boolean changed = !names.equals(order);
    order = names;
    return changed;
  }

  void setCounts(Map<String, Integer> counts) {
    this.counts = counts;
  }

  void setItems(Set<Integer> ids) {
    items = ids;
  }

  void setMissing(List<String> list) {
    missing = list;
  }

  List<String> missing() {
    return missing;
  }

  /** Whether the bank's kit filter shows this item ID. */
  boolean inBankFilter(int id) {
    return !hiddenVariants.contains(id)
        && (items.contains(id)
            || plugin.spellbook().capeNeeded() && SpellbookSwitch.MAGIC_CAPES.contains(id));
  }

  /** How many of this item ID the run needs, or 0. */
  int count(int id) {
    String name = kitName(id);
    return name == null ? 0 : counts.get(name);
  }

  /** The kit item name this item ID counts as, or null. */
  private String kitName(int id) {
    for (Map.Entry<String, Integer> entry : counts.entrySet())
      for (int known : FarmingData.IDS.getOrDefault(entry.getKey(), new int[0]))
        if (known == id) return entry.getKey();
    return null;
  }

  /**
   * How many more of this kit item you still need to take out of the bank: what the run needs
   * minus what's in your inventory, worn, or (for runes) in the rune pouch. -1 if it isn't kit.
   */
  int remaining(int id) {
    String name = kitName(id);
    if (name == null) return -1;
    int need = counts.get(name);
    int have = 0;
    Set<Integer> ids = new HashSet<>();
    for (int known : FarmingData.IDS.getOrDefault(name, new int[0])) ids.add(known);
    for (int container : new int[] {InventoryID.INV, InventoryID.WORN}) {
      ItemContainer containerItems = client.getItemContainer(container);
      if (containerItems == null) continue;
      for (Item item : containerItems.getItems())
        if (item.getId() > 0 && ids.contains(itemManager.canonicalize(item.getId())))
          have += item.getQuantity();
    }
    if (isRune(name))
      for (Map.Entry<Integer, Integer> rune : pouchRunes().entrySet())
        if (ids.contains(rune.getKey())) have += rune.getValue();
    return Math.max(0, need - have);
  }

  private static boolean isRune(String name) {
    return name.endsWith(" rune");
  }

  /** Rune item IDs the run needs, whether or not you have them yet. */
  Set<Integer> runesNeeded() {
    Set<Integer> ids = new HashSet<>();
    for (String name : counts.keySet())
      if (isRune(name)) {
        int id = FarmingData.id(name);
        if (id > 0) ids.add(id);
      }
    return ids;
  }

  /**
   * Before a run: rune item IDs the run still needs that you aren't carrying (pouch + inventory),
   * when your rune pouch is in the inventory, so it can be set up. Empty otherwise.
   */
  Set<Integer> pouchShortfall() {
    if (plugin.guide() != null || missing.isEmpty()) return Collections.emptySet();
    if (!plugin.account().holdingUnnoted(FarmingData.itemIds("Rune pouch")))
      return Collections.emptySet();
    // A full pouch of this run's runes (e.g. 3 kinds when it needs 4): the rest go loose in the
    // inventory, and the bank's kit filter already shows them unticked, so nothing to set up.
    Set<Integer> needed = runesNeeded();
    Set<Integer> inPouch = new HashSet<>();
    for (Map.Entry<Integer, Integer> rune : pouchRunes().entrySet())
      if (rune.getValue() > 0) inPouch.add(rune.getKey());
    if (inPouch.size() >= pouchKinds() && needed.containsAll(inPouch)) return Collections.emptySet();
    Set<Integer> shortRunes = new HashSet<>();
    for (String name : counts.keySet()) {
      if (!isRune(name)) continue;
      int id = FarmingData.id(name);
      if (id > 0 && remaining(id) > 0) shortRunes.add(id);
    }
    return shortRunes;
  }

  /** How many kinds of rune your pouch holds: 4 in a divine rune pouch, else 3. */
  int pouchKinds() {
    return plugin.account().holdingUnnoted(DIVINE_POUCHES) ? 4 : 3;
  }

  void setPouchHint(String hint) {
    pouchHint = hint;
  }

  String pouchHint() {
    return pouchShortfall().isEmpty() ? null : pouchHint;
  }

  /** Rune item IDs and amounts inside the rune pouch, read from its varbits. */
  Map<Integer, Integer> pouchRunes() {
    Map<Integer, Integer> runes = new LinkedHashMap<>();
    EnumComposition types = client.getEnum(EnumID.RUNEPOUCH_RUNE);
    for (int[] slot : POUCH_SLOTS) {
      int type = client.getVarbitValue(slot[0]);
      int amount = client.getVarbitValue(slot[1]);
      if (type <= 0 || amount <= 0 || types == null) continue;
      int id = types.getIntValue(type);
      if (id > 0) runes.merge(id, amount, Integer::sum);
    }
    return runes;
  }

  /** Whether this varbit is one of the rune pouch's slots. */
  static boolean isPouchVarbit(int varbitId) {
    for (int[] slot : POUCH_SLOTS) if (varbitId == slot[0] || varbitId == slot[1]) return true;
    return false;
  }

  /**
   * One slot per kit item, in Kit tab order. Each slot uses the variant you actually have in the
   * bank or inventory (e.g. your ring of wealth's charge), so it shows that item or its
   * placeholder. Also decides which spare variants the filter hides.
   */
  int[] bankLayout() {
    Set<Integer> have = new HashSet<>();
    Set<Integer> bank = plugin.account().bank();
    if (bank != null) have.addAll(bank);
    // Inventory and worn too: an axe or whistle you're wearing is one you own.
    for (int container : new int[] {InventoryID.INV, InventoryID.WORN}) {
      ItemContainer containerItems = client.getItemContainer(container);
      if (containerItems != null)
        for (Item item : containerItems.getItems())
          if (item.getId() > 0) have.add(itemManager.canonicalize(item.getId()));
    }
    List<Integer> slots = new ArrayList<>();
    List<Integer> seeds = new ArrayList<>();
    Set<Integer> hidden = new HashSet<>();
    List<String> names = new ArrayList<>(order);
    if (plugin.spellbook().capeNeeded()) names.add("Magic cape"); // to switch spellbook before the run
    for (String name : names) {
      int[] ids = FarmingData.IDS.getOrDefault(name, new int[0]);
      if (ids.length == 0) continue;
      int chosen = FarmingData.bestOwned(name, have);
      if (chosen <= 0) chosen = ids[0];
      boolean seed = name.endsWith(" seed") || name.endsWith(" sapling");
      if (!slots.contains(chosen) && !seeds.contains(chosen)) (seed ? seeds : slots).add(chosen);
      // One quetzal whistle is enough: show the best you own and hide the rest (IDS lists the
      // best first).
      if (name.equals("Quetzal whistle") || name.equals("Axe"))
        for (int id : ids) if (id != chosen) hidden.add(id);
    }
    hiddenVariants = hidden;
    // Seeds and saplings start the second row (slot 9): the first row is the outfit you put on,
    // so they're the first thing withdrawn into the inventory.
    if (!seeds.isEmpty()) {
      while (slots.size() < FIRST_ROW) slots.add(-1);
      slots.addAll(FIRST_ROW, seeds);
    }
    return slots.stream().mapToInt(Integer::intValue).toArray();
  }
}

package com.yonwi.farming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

/**
 * Makes the option the guide wants the left-click one: the rune pouch's Configure, the spellbook
 * switch, paying the gardener, and the teleport, ring, tree or boat for the trip. Option names
 * are from RuneLite's Menu Entry Swapper.
 */
final class MenuSwaps {
  /** Plain teleport options, after one naming the destination. */
  private static final List<String> TELEPORT_OPTIONS =
      Arrays.asList(
          "teleport", "farm teleport", "tele to poh", "travel", "teleport menu", "squeeze-through", "follow");
  /** Objects and NPCs on the way: house spirit tree, portal nexus, jewellery box, the Tree Gnome Village railing and Elkoy. */
  private static final String[] ON_THE_WAY = {
    "spirit tree", "portal nexus", "jewellery box", "railing", "elkoy", "mountain guide"
  };
  /** No option ranked: nothing to move. */
  private static final int UNRANKED = 9;

  @Inject private Client client;
  @Inject private FarmingPlugin plugin;

  /** How an item's name starts in game menus, lower case (some are abbreviated there). */
  static String menuName(String itemName) {
    String name = itemName.toLowerCase(Locale.ROOT);
    return name.equals("construction cape") ? "construct. cape" : name;
  }

  /** After the menu is sorted: puts the wanted option on top. */
  void swap() {
    Guidance step = plugin.guide();
    boolean menuOpen = client.isMenuOpen();
    // The rune pouch doesn't hold what the run needs: Configure is the left-click.
    if (step == null && !menuOpen && !plugin.kit().pouchShortfall().isEmpty() && swapPouchConfigure())
      return;
    if (step == null && plugin.spellbook().hint() != null && !menuOpen) {
      swapForSpellbookSwitch();
      return;
    }
    // Paying the gardener (protection, or removing the tree): "Pay" is his left-click.
    if (step != null && !menuOpen && plugin.targets().paysGardener(step, step.phase)) {
      swapGardenerPay(step);
      return;
    }
    if (step == null || !step.phase.equals("Travel") && !plugin.progress().houseReturn() || menuOpen)
      return;
    swapForTravel(step);
  }

  private boolean swapPouchConfigure() {
    MenuEntry[] entries = client.getMenuEntries();
    for (MenuEntry entry : entries)
      if (target(entry).contains("rune pouch") && option(entry).equals("configure")) {
        moveToLeftClick(entries, entry);
        return true;
      }
    return false;
  }

  /**
   * Before a run that needs another spellbook: the magic cape's Spellbook, the altar's option for
   * that book, or (when the house is the way) the Construction cape's or tablet's Tele to POH.
   */
  private void swapForSpellbookSwitch() {
    String word = plugin.spellbook().word();
    if (word == null) return;
    MenuEntry[] entries = client.getMenuEntries();
    String[][] wanted = {
      {"magic cape", "spellbook"},
      {"max cape", "spellbook"},
      {"altar of the occult", word}, // options: Venerate, Standard, Ancient, Lunar (+ Arceuus)
      {"occult altar", word},
      {"dark altar", word},
      {"dark altar", "venerate"},
      {"construct", "tele to poh"}, // the game names it "Construct. cape(t)"
      {"teleport to house", "break"}
    };
    for (String[] want : wanted) {
      boolean toHouse = want[0].equals("construct") || want[0].equals("teleport to house");
      if (toHouse && !"house".equals(plugin.spellbook().route())) continue;
      for (MenuEntry entry : entries)
        if (target(entry).contains(want[0]) && option(entry).equals(want[1])) {
          moveToLeftClick(entries, entry);
          return;
        }
    }
  }

  /** With more than one patch he has "Pay (tree patch)", "Pay (fruit tree)"…: the one for this patch. */
  private void swapGardenerPay(Guidance step) {
    int gardenerId = TargetData.GARDENERS.getOrDefault(step.patchId, -1);
    MenuEntry[] entries = client.getMenuEntries();
    MenuEntry pay = null;
    for (MenuEntry entry : entries) {
      NPC npc = entry.getNpc();
      String option = option(entry);
      if (npc == null || npc.getId() != gardenerId || !option.startsWith("pay")) continue;
      boolean fruit = option.contains("fruit");
      if (pay == null || fruit == step.kind.equals("fruit")) pay = entry;
    }
    if (pay != null) moveToLeftClick(entries, pay);
  }

  /**
   * While travelling: the cloak or ring teleport, the fairy ring's Last-destination (when it's
   * already this code) or Configure, and the spirit tree's Travel (Tree on a spiritual fairy tree).
   */
  private void swapForTravel(Guidance step) {
    MenuEntry[] entries = client.getMenuEntries();
    MenuEntry best = bestTeleport(step, entries);
    // Exact swaps first (worn items use the destination as the option, e.g. "Ardougne Farm").
    for (String[] want : wantedOptions(step))
      for (MenuEntry entry : entries) {
        String option = option(entry);
        boolean exact = want[1].equals("teleport") || want[1].equals("tree") || want[1].equals("charter");
        if (!target(entry).contains(want[0])
            || !(exact ? option.equals(want[1]) : option.contains(want[1]))) continue;
        moveToLeftClick(entries, entry);
        return;
      }
    if (best != null) moveToLeftClick(entries, best);
  }

  /** {target contains, option contains} pairs for this trip, best first. */
  private List<String[]> wantedOptions(Guidance step) {
    String travel = step.travel.toLowerCase(Locale.ROOT);
    String code = FarmingPlanner.fairyCode(step.travel);
    List<String[]> wanted = new ArrayList<>();
    if (step.travel.startsWith("Ardougne cloak")) wanted.add(new String[] {"ardougne cloak", "farm"});
    if (step.travel.startsWith("Explorer's ring")) wanted.add(new String[] {"explorer's ring", "teleport"});
    // The Construction cape's own portals (Taverley, Brimhaven) are under "Teleport"; its
    // "Tele to POH" is only for trips through your house.
    // (In menus the game calls it "Construct. cape(t)", so match on "construct".)
    if (step.travel.startsWith("Construction cape")) wanted.add(new String[] {"construct", "teleport"});
    // Eternal or charged teleport crystal: its "Lletya" option.
    if (travel.contains("lletya")) wanted.add(new String[] {"teleport crystal", "lletya"});
    // Standard spells: "Cast", not an alternative like Varrock's Grand Exchange.
    String spell = step.spell;
    if (spell != null && !spell.equals("House"))
      wanted.add(new String[] {spell.toLowerCase(Locale.ROOT) + " teleport", "cast"});
    if (code != null) {
      wanted.add(new String[] {"fairy", "last-destination (" + code.toLowerCase(Locale.ROOT)});
      wanted.add(new String[] {"fairy", "configure"});
    }
    // A charter ship (e.g. Catherby to Corsair Cove): the crew's "Charter-to <place>" when it's
    // already this destination (it remembers your last one), otherwise plain "Charter".
    if (travel.contains("charter")) {
      String port = FarmingPlanner.charterPort(travel);
      if (plugin.progress().chartered()) {
        // Off the ship, then on: the gangplank's Cross and the rowboat's Travel.
        wanted.add(new String[] {"gangplank", "cross"});
        wanted.add(new String[] {"rowboat", "travel"});
      } else {
        if (port != null) wanted.add(new String[] {"trader crew", "charter-to " + port});
        wanted.add(new String[] {"trader crew", "charter"});
      }
    }
    if (travel.contains("spirit tree")) {
      wanted.add(new String[] {"spiritual fairy tree", "tree"});
      wanted.add(new String[] {"spirit tree", "travel"});
    }
    return wanted;
  }

  /**
   * Any other teleport item on this step (talisman, capes, jewellery…): prefer an option naming
   * the destination, e.g. "Falador Park" or "Xeric's Glade", then Teleport / Tele to POH, then Rub.
   */
  private MenuEntry bestTeleport(Guidance step, MenuEntry[] entries) {
    String travel = step.travel.toLowerCase(Locale.ROOT);
    int arrow = step.travel.indexOf('→');
    String place =
        arrow < 0 ? "" : travel.substring(arrow + 1).split("[,;]| then ")[0].replace("→", "").trim();
    String destination = FarmingInventoryOverlay.destination(step.travel);
    // House routes (house fairy ring, spirit tree, jewellery box, nexus) want "Tele to POH", not
    // the cape's portal list.
    boolean toHouse = Targets.throughHouse(travel);
    MenuEntry best = null;
    int bestRank = UNRANKED;
    for (MenuEntry entry : entries) {
      if (!isOnRoute(step, travel, target(entry))) continue;
      int rank = rank(option(entry), place, destination, toHouse);
      if (rank < bestRank) {
        best = entry;
        bestRank = rank;
      }
    }
    return best;
  }

  /** Whether a menu target is this step's item, or an object or NPC the route uses. */
  private static boolean isOnRoute(Guidance step, String travel, String target) {
    boolean ours = false;
    for (String item : step.items) ours |= target.startsWith(menuName(FarmingPlanner.normalize(item)));
    for (String thing : ON_THE_WAY) ours |= target.contains(thing) && travel.contains(thing.split(" ")[0]);
    ours |= target.contains("portal") && travel.contains("portal");
    return ours;
  }

  /** 0 for the option naming the destination, 1 for a plain teleport, 2 for Rub, else unranked. */
  private static int rank(String option, String place, String destination, boolean toHouse) {
    if (toHouse && option.equals("tele to poh")) return 0;
    boolean namesPlace =
        !place.isEmpty() && option.contains(place)
            || destination.length() > 3 && option.contains(destination)
            // Worn jewellery shortens it: the worn ring's "Falador" for Falador Park.
            || option.length() > 3 && !place.isEmpty() && place.startsWith(option);
    if (namesPlace) return 0;
    if (TELEPORT_OPTIONS.contains(option)) return 1;
    return option.equals("rub") ? 2 : UNRANKED;
  }

  /** The last menu entry is the left-click option. */
  private void moveToLeftClick(MenuEntry[] entries, MenuEntry entry) {
    List<MenuEntry> list = new ArrayList<>(Arrays.asList(entries));
    list.remove(entry);
    list.add(entry);
    // Item ops 4 and 5 (e.g. the cloak's Farm Teleport, the cape's Tele to POH) are
    // CC_OP_LOW_PRIORITY, which the game never uses as the left-click: it opens the menu or picks
    // the next option instead. Menu Entry Swapper raises them to CC_OP for the same reason.
    if (entry.getType() == MenuAction.CC_OP_LOW_PRIORITY) entry.setType(MenuAction.CC_OP);
    // A deprioritised entry on top also makes a left-click open the menu.
    entry.setDeprioritized(false);
    plugin.debug().event("left-click: " + Text.removeTags(entry.getOption()) + " " + Text.removeTags(entry.getTarget()));
    client.setMenuEntries(list.toArray(new MenuEntry[0]));
  }

  /**
   * In a right-click submenu, e.g. the construction cape's Teleport list, the route's destination
   * and the option that opens it are drawn in the highlight colour.
   */
  void colourDestination(Guidance step) {
    if (!client.isMenuOpen()) return;
    String word = FarmingInventoryOverlay.destination(step.travel).split(" ")[0];
    if (word.length() < 4) return;
    String colour = String.format("<col=%06x>", FarmingInventoryOverlay.TARGET.getRGB() & 0xFFFFFF);
    for (MenuEntry entry : client.getMenu().getMenuEntries()) {
      Menu sub = entry.getSubMenu();
      if (sub == null) continue;
      for (MenuEntry choice : sub.getMenuEntries()) {
        String option = choice.getOption();
        if (option == null || option.startsWith("<col=")) continue;
        if (!option.toLowerCase(Locale.ROOT).contains(word)) continue;
        choice.setOption(colour + option + "</col>");
        if (!entry.getOption().startsWith("<col=")) entry.setOption(colour + entry.getOption() + "</col>");
      }
    }
  }

  private static String option(MenuEntry entry) {
    return Text.removeTags(entry.getOption()).toLowerCase(Locale.ROOT);
  }

  private static String target(MenuEntry entry) {
    return Text.removeTags(entry.getTarget()).toLowerCase(Locale.ROOT);
  }
}

package com.yonwi.farming;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;

/**
 * When to note produce at a tool leprechaun: before leaving a herb patch, on the way in, or when
 * the inventory fills while picking.
 */
final class NotingAdvice {
  private static final int INVENTORY_SLOTS = 28;
  /** Room to keep beyond a patch's expected herbs before noting is suggested. */
  private static final int SPARE_SLOTS = 2;

  @Inject private Client client;
  @Inject private FarmingPlugin plugin;

  private volatile String advice;
  /** Picking herbs that will likely fill the inventory: herbs and leprechaun are next. */
  private volatile boolean soon;
  /** The patch whose leprechaun you've been told to note at on the way in, or null. */
  private String onWayInPatch;
  /** Noting costs per pair of stages ("from>to"): {here, detour at the next patch}, in tiles. */
  private final Map<String, int[]> costs = new HashMap<>();
  /** Debug: noting advice last logged, and the stage last logged as started. */
  private String lastNoteLog;
  private String lastStageLog;

  /** Shown when produce should be noted now, with the leprechaun and produce highlighted. */
  String advice() {
    return advice;
  }

  boolean soon() {
    return soon;
  }

  /** Works out this tick's advice. */
  void update(Guidance step, Player player, TileObject patch, NPC leprechaun) {
    soon = false;
    advice = advise(step, player, patch, leprechaun);
  }

  /** The unnoted produce to note at the leprechaun on this step: grimy herbs, fruit or bark. */
  Set<Integer> produce() {
    Guidance step = plugin.guide();
    if (step == null || step.kind.equals("herb")) return HarvestTracker.GRIMY_HERBS;
    return step.produce.isEmpty() ? Collections.emptySet() : FarmingData.itemIds(step.produce);
  }

  private String advise(Guidance step, Player player, TileObject patch, NPC leprechaun) {
    ItemContainer inventory = client.getItemContainer(InventoryID.INV);
    if (inventory == null) return null;
    // Herbs, fruit, Calquat or Celastrus bark picked here and not yet noted.
    Set<Integer> produce = produce();
    int used = 0;
    int unnoted = 0;
    for (Item item : inventory.getItems())
      if (item.getId() > 0) {
        used++;
        if (produce.contains(item.getId())) unnoted++;
      }
    if (unnoted == 0) return null;
    int free = INVENTORY_SLOTS - used;
    boolean herbs = step.kind.equals("herb");
    // Herbs fill an open herb sack before the inventory, so its room counts too.
    int sackRoom = herbs ? plugin.harvest().sackRoom() : 0;
    Room room = new Room(free, sackRoom);
    if (herbs && noteBeforeLeaving(step, player, leprechaun, room))
      return "Note your herbs here: " + room + ", the next patch gives about " + step.herbsIfAlive;
    String onWayIn = noteOnWayIn(step, player, leprechaun, room);
    if (onWayIn != null) return onWayIn;
    return noteWhenFull(step, player, patch, leprechaun, room);
  }

  /** Free inventory slots and herb sack room, e.g. "5 free slots + 12 in the herb sack". */
  private static final class Room {
    final int free;
    final int sack;

    Room(int free, int sack) {
      this.free = free;
      this.sack = sack;
    }

    int total() {
      return free + sack;
    }

    @Override
    public String toString() {
      return free + " free slots" + (sack > 0 ? " + " + sack + " in the herb sack" : "");
    }
  }

  /**
   * Leaving a herb patch for another: if the next one's herbs won't fit with 2 to spare, note at
   * this patch's leprechaun first (e.g. Catherby before Troll Stronghold).
   */
  private boolean noteBeforeLeaving(Guidance step, Player player, NPC leprechaun, Room room) {
    return step.phase.equals("Travel")
        && "herb".equals(step.prevKind)
        && leprechaun != null
        && !client.getTopLevelWorldView().isInstance()
        && StepProgress.inPatchArea(step.prevPatchId, player.getWorldLocation())
        && room.total() < step.herbsIfAlive + SPARE_SLOTS
        && noteHereShorter(step.prevPatchId, step.patchId, step.travel);
  }

  /**
   * On the way in, when this patch's herbs won't fit and the leprechaun comes before the patch
   * (e.g. Falador): note as you pass him. Once advised it stays until you've noted or started
   * picking. When he's past the patch (e.g. Catherby), pick until full instead.
   */
  private String noteOnWayIn(Guidance step, Player player, NPC leprechaun, Room room) {
    WorldPoint at = TargetData.PATCH_POINTS.get(step.patchId);
    WorldPoint here = player.getWorldLocation();
    boolean approaching =
        step.kind.equals("herb")
            && (step.phase.equals("Travel") || step.phase.equals("Harvest"))
            && !step.patchId.equals(plugin.harvest().pickingPatch())
            // The same rule as noting before leaving: room for this patch's herbs if it's alive,
            // with 2 to spare.
            && room.total() < step.herbsIfAlive + SPARE_SLOTS
            && at != null
            && at.getPlane() == here.getPlane()
            // In the patch's own area (RuneLite's farming regions for it), not just anywhere.
            && TargetData.HERB_REGIONS
                .getOrDefault(step.patchId, Collections.emptySet())
                .contains(here.getRegionID());
    // Where he stands: NPCs only show within about 15 tiles, so until then his known spot.
    WorldPoint leprechaunAt =
        leprechaun != null
            ? leprechaun.getWorldLocation()
            : at == null ? null : TargetData.nearestLeprechaun(at);
    String text = "Note your herbs on the way: " + room + ", this patch gives about " + step.herbsIfAlive;
    if (!approaching) onWayInPatch = null;
    else if (step.patchId.equals(onWayInPatch)) return text;
    else if (leprechaunAt != null && leprechaunAt.distanceTo(here) < at.distanceTo(here)) {
      onWayInPatch = step.patchId;
      return text;
    }
    return null;
  }

  /**
   * Otherwise noting only happens when the inventory fills up while picking: pick until full, note
   * at that patch's leprechaun, then finish. Sets {@link #soon} when that's likely.
   */
  private String noteWhenFull(Guidance step, Player player, TileObject patch, NPC leprechaun, Room room) {
    if (!plugin.progress().arrived(step.patchId, player)) return null;
    boolean herbs = step.kind.equals("herb");
    boolean harvesting = step.phase.equals("Harvest");
    boolean stillToPick = stillToPick(patch);
    // Herbs likely to fill the inventory before the patch is done: the herbs and the leprechaun
    // are next (orange), so noting is ready before it's full.
    int left = Math.max(1, step.herbsIfAlive - plugin.harvest().pickedAt(step.patchId));
    soon = herbs && harvesting && stillToPick && room.total() > 0 && room.total() < left;
    // Composting, the last step here, with a herb patch next: if you'll have to note before it
    // and this leprechaun is the shorter walk, the herbs and him are next, not the teleport (it
    // turns into "note here" once compost is done).
    soon |=
        herbs
            && step.phase.equals("Compost")
            && "herb".equals(step.nextKind)
            && leprechaun != null
            && room.total() < step.nextHerbsIfAlive + SPARE_SLOTS
            && noteHereShorter(step.patchId, step.nextPatchId, step.nextTravel);
    // Full with more still to harvest (any crop): note at this patch's leprechaun, then finish.
    // Herbs still go into an open herb sack with room, however full the inventory is.
    if (harvesting && stillToPick && room.total() == 0)
      return "Inventory full: note your "
          + (herbs ? "herbs" : step.produce.toLowerCase(Locale.ROOT))
          + " at this leprechaun, then finish "
          + (step.kind.equals("celastrus") ? "harvesting" : "picking");
    return null;
  }

  private boolean stillToPick(TileObject patch) {
    if (patch == null) return false;
    ObjectComposition definition = plugin.scene().definition(patch);
    if (definition == null) return false;
    boolean stillToPick = false;
    for (String action : definition.getActions())
      stillToPick |=
          action != null
              && (action.toLowerCase(Locale.ROOT).startsWith("pick")
                  || action.toLowerCase(Locale.ROOT).startsWith("harvest"));
    return stillToPick;
  }

  /**
   * Whether noting at the previous herb patch's leprechaun is a shorter walk than noting at this
   * stage's: here it's patch to leprechaun (you teleport from there); there it's the detour from
   * where its teleport lands, via its leprechaun, to the patch (about 0 when he's on the way in,
   * as at Falador). True when either isn't known.
   */
  private boolean noteHereShorter(String fromPatch, String toPatch, String toTravel) {
    if (fromPatch == null || toPatch == null || toTravel == null) return true;
    String key = fromPatch + ">" + toPatch;
    int[] known = costs.get(key);
    if (known == null) {
      WorldPoint previous = TargetData.HERB_POINTS.get(fromPatch);
      WorldPoint next = TargetData.HERB_POINTS.get(toPatch);
      if (previous == null || next == null) return true;
      WorldPoint leprechaunHere = TargetData.nearestLeprechaun(previous);
      WorldPoint leprechaunNext = TargetData.nearestLeprechaun(next);
      if (leprechaunHere == null || leprechaunNext == null) return true;
      WorldPoint landing = likelyLanding(TeleportData.landingsFor(toTravel), next);
      int here = walkTiles(previous, leprechaunHere);
      int detour =
          Math.max(
              0,
              walkTiles(landing, leprechaunNext) + walkTiles(leprechaunNext, next) - walkTiles(landing, next));
      known = new int[] {here, detour};
      // Only kept once the map is loaded, so a straight-line guess isn't stuck.
      if (WorldPath.ready()) {
        costs.put(key, known);
        plugin.debug().log(
            "note costs " + key + ": here " + here + " tiles, detour at the next patch " + detour
                + " tiles (landing " + landing.getX() + "," + landing.getY() + ")");
      }
    }
    return known[0] < known[1];
  }

  /** Tiles to walk between two spots along real paths, or straight-line tiles without a route. */
  private static int walkTiles(WorldPoint from, WorldPoint to) {
    if (from.getPlane() != to.getPlane()) return 1000;
    if (from.distanceTo(to) <= 1) return 0;
    List<WorldPoint> route = WorldPath.find(from, to);
    return route.isEmpty() ? from.distanceTo(to) : route.size();
  }

  /**
   * Where a route's teleport most likely lands: the spot its matching teleport rows name most
   * often (a ring's or spell's several rows agree), nearest the patch on a tie; the patch itself
   * when none is within 100 tiles.
   */
  static WorldPoint likelyLanding(List<WorldPoint> landings, WorldPoint patch) {
    Map<WorldPoint, Integer> count = new HashMap<>();
    for (WorldPoint landing : landings)
      if (landing.getPlane() == patch.getPlane() && landing.distanceTo(patch) < 100)
        count.merge(landing, 1, Integer::sum);
    WorldPoint best = patch;
    int most = 0;
    for (Map.Entry<WorldPoint, Integer> entry : count.entrySet())
      if (entry.getValue() > most
          || entry.getValue() == most && entry.getKey().distanceTo(patch) < best.distanceTo(patch)) {
        best = entry.getKey();
        most = entry.getValue();
      }
    return best;
  }

  /** Debug: a line when a stage starts, and when noting advice turns on, off or changes. */
  void log(Guidance step, NPC leprechaun) {
    ItemContainer inventory = client.getItemContainer(InventoryID.INV);
    int used = 0;
    int unnoted = 0;
    Set<Integer> produce = produce();
    if (inventory != null)
      for (Item item : inventory.getItems())
        if (item.getId() > 0) {
          used++;
          if (produce.contains(item.getId())) unnoted++;
        }
    int free = INVENTORY_SLOTS - used;
    if (!step.patchId.equals(lastStageLog)) {
      lastStageLog = step.patchId;
      plugin.debug().log(
          "stage: " + step.patchId + " (" + step.kind + ") · " + step.travel + " · steps " + step.phases
              + " · " + free + " free slots · expected herbs " + step.herbsIfAlive
              + " (with deaths " + step.herbsPerPatch + ")");
    }
    String state = advice + "|" + soon;
    if (state.equals(lastNoteLog)) return;
    lastNoteLog = state;
    plugin.debug().log(
        "noting: " + (advice != null ? "advice '" + advice + "'" : soon ? "soon (orange)" : "off")
            + " · " + step.phase + " · free " + free + " · unnoted produce " + unnoted
            + " · expected " + step.herbsIfAlive + " · picked here " + plugin.harvest().pickedAt(step.patchId)
            + " · previous stage " + step.prevPatchId + " (" + step.prevKind + ") · leprechaun "
            + (leprechaun == null
                ? "none"
                : leprechaun.getWorldLocation().getX() + "," + leprechaun.getWorldLocation().getY()));
  }
}

package com.yonwi.farming;

